INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0217bf8acb7c3bc93472', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''m assuming NRW are the management agency who you''d go to to try and do that in what I call peacetime, rather than the crisis of where you have the fire.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=906&l=en', NULL, 51.7, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'Sector bodies', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.398594', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771740', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('0222e53fdad41a348862', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '5. What action is the Welsh Government taking to meet its social housing targets? OQ64420', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Laura Anne Jones', '', '4562', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', '', NULL, 77.0, 'Medium', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Housing minister', '', 'housing targets; social housing', 0, '2026-08-04T14:03:05.229570', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768212', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('02708a42a4ea3ed2e869', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'It''s very simple. Does the new Welsh Government continue to accept the principle, where new duties have been created, be it on local government or the health service, that funding follows legislation? I''m thinking in particular about the right to adequate housing.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Huw Thomas', '', '12156', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2139&l=en', NULL, 86.2, 'High', 'digest', 'homelessness; committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee; adequate housing; right to adequate housing', 0, '2026-09-22T11:55:09.433224', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770385', NULL, NULL, NULL, NULL);
