INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('372d1c180c20053f4df0', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, thank you, Minister. Have we done any work yet on the impact that the wildfires and the dry weather this summer have had on biodiversity—loss of habitat and things like that? I was just wondering what work has been done on that, if any.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Paul Rock', '', '12176', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1971&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.557515', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772024', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('374612f9411705ad08c4', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Disappointing.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2703&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.687142', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771878', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('374d429cb82434025734', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Were you content, then, with the evaluation of the pilots, that vulnerable people had been engaged with enough?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1201&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.862992', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769843', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('37ccf7d2637034b443ea', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Are you as chief vet concerned by the residue in animal-origin products coming out of Brazil with the information you have at the moment?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5380&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.019586', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771863', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('37f63b28f0087214e007', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'During the supplementary budget process, we, at Reform, were clear that one of our key red lines was the removal of Wales''s international spending commitments. Now, the finance Minister today has spoken about the challenges that lie ahead with the budget, and, over the weekend, she said that there may well be some cuts in some areas of budget, when speaking to the media. Given that cuts are clearly on the table, will the finance Minister commit today to cutting Government spending in foreign countries before she considers cutting spending in Wales?', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Benjamin Hodge Mckenna', '', '12142', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=3104&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-09-19T12:39:16.939263', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769521', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('384490680c5095cd9ebd', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'There is quite a lot to unpick in that question. There is a reference there to the need to work in a consensual way. I start this term in the way that I started the first term post election in making it very, very clear that this is a Government that wants to reach out and work in a way that serves the people of Wales in a constructive way. So, I make that point.

 We''re a Government that hit the ground running with a 100-day plan that we were able to deliver on, setting the foundations for what will be the programme for government to be presented in the very near future. This is a Government that takes seriously the faith put in us by the people of Wales, dealing with many different challenges, because the Member knows governing isn''t always easy. It is about prioritising, but the more that we can work together, have clarity in what we are trying to achieve for the people of Wales, well, the better our chances of giving them the outcomes that they deserve. It has been a very, very busy summer of working with many, many partners in making sure that we move forward with real purpose.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=1297&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'programme for government', 0, '2026-09-19T12:39:25.009179', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769019', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('39b5794907bb7a02f37b', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you for the question. I think that''s a really important point. So, once again, we are working across the Government on a food strategy and part of that is taking a strategic approach of looking at reducing food poverty. So, it''s not just those emergency support packages, which, unfortunately, are necessary until people are paid well enough and there''s a benefit system there in place for them, which is going to be crucial, but to ensure that we improve that access to food that is healthy and affordable and food that''s nutritious, too. That''s something that''s central to the strategy and our ambitions as a Government. So, of course, we have our food partnerships in place. I think we did look at this thoroughly in this committee and that report was extremely helpful. I think it was the last report of the previous committee in the previous Senedd. And that report was entirely clear that tackling food poverty and ensuring that we improve health outputs for people in poverty go hand in hand. Therefore, I think that that funding that I released last week was a part of that. Of course, it was intentional, as we''re facing the winter and thinking about what''s to come, and the pressures we will face in winter. But there was a long-term element involved in that as well. So, working through our local food partnerships, and the co-ordinators we have who are funded from my portfolio, is something that will help with that.

 I will have input into that food strategy in order to ensure that we do meet that demand and respond to that issue, which, frankly, of course, is at the root of health issues. We saw, last week, I think, didn''t we, obesity, for instance, within children who are in poverty exists in particular—the health outcomes. I remember reading a report from the Royal College of Paediatrics and Child Health that showed that the majority of young people who are getting planned or urgent treatment are children living in poverty. So, this isn''t just something that''s about being merciful and something that''s good to do, but it will ultimately save us money as a Government, not to mention, of course, the human cost.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1761&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.749197', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771154', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3a199587c1599b916c0a', 'calendar', 'Senedd forward look', 'Legislation Committee — 21 September 2026, 12.00', 'Legislation Committee is scheduled to meet on 21 September 2026 at 12.00.
Meeting status: Confirmed; Hybrid
This is an opportunity to influence: committee papers and any call for written evidence are normally published in the two weeks beforehand.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=986&MId=16254', '2026-09-21', '', '', '', '', '', 'Legislation Committee', '', '16254', '', '2026-09-21', 48.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Legislation Committee; written evidence', 0, '2026-08-04T14:04:40.425615', 'https://business.senedd.wales/mgWebService.asmx#GetAllMeetingsByDate', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3a6d8aa0f9d0ea87d273', 'plenary_transcript', 'Plenary', '6. Statement by the Deputy Minister for Public and Preventative Health: Priorities for Public and Preventative Health', 'Well, I''m glad you agree with the priority that we''ve put on tackling waiting lists and the investment that we''ve set out in the supplementary budget in order to do that. I hope, indeed, that Members would reflect on what voting against that supplementary budget would mean in terms of the investment that we need in our NHS and across other preventative health measures. There''s investment in the supplementary budget on the swimming initiative for schools as well. So, voting against the supplementary budget this afternoon does have serious consequences in terms of the ability of our NHS to respond to the demands it''s facing now and the backlog that we have inherited from the previous Government, which absolutely impacts on the issues that you mentioned about the provision of health services in our rural communities. I am also from rural west Wales and know the challenges. As the First Minister set out earlier this afternoon, our ambition is to make sure that we look at rural-proofing, to make sure that the cost of delivery of services really does adequately reflect the actual costs in terms of what''s being funded, and that is a key central part. But I''d urge Members across this Chamber to make sure that they support the supplementary budget, to make sure of exactly what you mentioned, in terms of tackling the waiting lists and making sure our health and social care system is on a sustainable footing.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Nerys Evans', '', '261', '', '', 'Plenary', '6. Statement by the Deputy Minister for Public and Preventative Health: Priorities for Public and Preventative Health', '16085', 'http://www.senedd.tv/en/16085?startPos=16878&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:09.918256', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767878', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3a7dbb3ae700430c9e6c', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''m aware, Chair, that Dylan Hughes has just been to Singapore. So over to you, Mr Hughes. [ Laughter .]', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2998&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.590180', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770468', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3a7e5e3dfa307c0b54d9', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As such, I will helpfully remind Members if they exceed the time. I ask Members to work with me; there are a lot of speakers down for this debate.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23410&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.523612', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767984', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3b22e0ada82475d06b0e', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Could I just make a technical point here, if I may?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dylan Hughes', '', '', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4691&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.930159', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770609', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3b4f72e9f7e6c758d10a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you very much, Tom. So, I guess this is the point when we get to ask the gentlemen on the Zoom call any questions you may have. So, Peter, I think you want to talk about the evaluation of the pilots.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=141&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.697237', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769802', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3c2e05386b03fe8784f2', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''ve had discussions about this issue, quite clearly, over the past weeks and months. If I may ask my colleague Dylan Hughes if he will address this, because he''s actually on the front line in this.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=609&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.145036', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770371', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3c8e0b8a44a5d773cdca', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'And I think the paperwork and the explanatory memorandums that we get as a committee, as well as the Senedd, need to be adequate and very well written. And we''ve seen examples in this Senedd where they haven''t been well written and well explained, where our clerking team have then had to unpick it to be able to work out what on earth is going on. It shouldn''t be down to our clerking team to do that. It should be the work of the Government to produce that information for us. And that''s something that I''d like you to reflect on as, obviously, the timescale with an LCM is that it needs to be presented to the Senedd within two weeks. But, obviously, the documentation that goes hand in hand with that needs to be accurate and easy to understand for us to be able to do our scrutiny role properly. That''s something that I hope you''ll take away from this meeting—that it''s something that we will look at, and, as part of our scrutiny of LCMs, is something that we will do.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3782&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'LCM; Legislation Committee', 0, '2026-09-22T11:55:09.742298', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770431', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3d22ca7f988f94317b91', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'But you are rejecting the deal that would have secured £120 million additional spending on additional learning needs, as you brought to the table. So, I remain, despite that contribution, totally flabbergasted.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26155&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.824139', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767994', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3d54d34f1ba659965d56', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'One thing that we have concerns with as well is—. We''ve been speaking to some electoral services teams in England—one in particular—who have been extensive in data matching and mining for a number of years, which they''ve done work with. In terms of their evaluation of their data sets within their authorities, they use council tax and they use education. We''ve talked about physically getting hold of information. Sandra has alluded to those being the two key sets.

 While you can use your education records and obviously add someone to the register automatically in that sense, without that second data source—. It''s actually having the ability to have information that allows you to add those people to the register. I think that''s the concern there: the quality of it and the access to it. They can get council tax, but finding that other second data source is going to be, I think, a struggle for a lot of people, based on Sandra''s experiences, from their evaluation of their data and from what we know from English local authorities who do data matching.

 The other thing that they flagged up as well is the checks. With this one local authority in particular, a lot of their other local data sources are verified against the electoral register, and they''ve said they can''t use data that has been verified. Again, as I said, the electoral register is considered one of the most comprehensive and complete data sources, so it''s that challenge of making sure that you''re not using data that has been verified against your own records.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=6932&l=en', NULL, 109.2, 'High', 'digest', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; evidence session', 0, '2026-09-18T11:33:49.687956', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769969', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3d7021da1680eecc01f5', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Fifteen years, and all your transport Minister could come up with is closing junctions. Now, one way to stop congestion is to stop cars getting onto the M4. I''ll give you that, but the people of Newport will not be very happy with that.

 I asked for initial costings. Costings for phase 1 is not the initial costings. You said during the election campaign your promises were fully costed. Then you''re downgrading them to initial costings. Then you''re downgrading it to costings for phase 1. So, you clearly haven''t got a plan. And if we do get those costings within the first 100 days, the 100 days ends during recess. So, we can''t scrutinise when you actually issue those, but we will be here in September, waiting to scrutinise those figures.

 But, First Minister, if your supplementary budget is voted down today, are you prepared to come back during the summer recess with a revised budget, or is this a part-time Plaid Government? Or are you content for the plans within your supplementary budget to languish for months upon months because you''re too stubborn to do a deal?', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Dan Thomas', '', '12147', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=1112&l=en', NULL, 66.0, 'Medium', 'digest', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet; Opposition housing leads', '', 'supplementary budget', 0, '2026-08-04T14:03:08.287615', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767490', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3d7a278620fbedd0ee03', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Anna, did you want to come in?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=601&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.356194', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771777', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3d8a7572fd4141d05038', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. I wanted to ask whether the Welsh Government plans to retain the existing tackling fuel poverty action plan and the 2035 targets. And if that is the case, do you plan on bringing any targets in the interim to check that progress is happening?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1342&l=en', NULL, 109.2, 'High', 'digest', 'energy_efficiency; committee_scrutiny', 'Housing system; Property & energy', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee; fuel poverty', 0, '2026-09-25T06:30:35.706999', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771224', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3dc64385a129f5559cc5', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I''ll start. I''m going to answer in a broad way, as you''d expect, probably, with that strategic overview. I think the real importance with funding is it''s not one-off funding and that that funding is put into budgets and ring-fenced for this activity on an ongoing basis. I think what we''ve seen so far is a response from the Welsh Government to support one-off related costs up to the 2027 election, but I think the real risk is that that isn''t ongoing. So, I think that''s the big strategic point we would want to get across.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Ian Bancroft', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=7078&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.713421', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769985', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3dd0b0bbccd2321fed46', 'calendar', 'Senedd forward look', 'Equality, Human Rights and Social Justice Committee — 16 September 2026, 09.30', 'Equality, Human Rights and Social Justice Committee is scheduled to meet on 16 September 2026 at 09.30.
Meeting status: Confirmed
This is an opportunity to influence: committee papers and any call for written evidence are normally published in the two weeks beforehand.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=983&MId=16246', '2026-09-16', '', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '', '16246', '', '2026-09-16', 48.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Equality, Human Rights and Social Justice Committee; written evidence', 0, '2026-08-04T14:04:40.405241', 'https://business.senedd.wales/mgWebService.asmx#GetAllMeetingsByDate', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3deed173d8cba527e0a6', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'The digitally enabled Cabinet Office is allowing us to track progress on various policy issues at the moment. If you are an aficionado of the Welsh Government website, you may have seen some digital dashboards that have been published recently, which will allow everyone to track that progress. I think that helps us to track progress on priorities. There isn''t a dashboard on legislation, as you''ll be very well aware. 

 My view, and colleagues more learned than me certainly might take a different view, is that the development around artificial intelligence—done well, used effectively, built through our training processes—does offer some opportunities to enhance the capacity and capability that we have within the system. I am slightly reticent, because there are clearly some horror stories around artificial intelligence and there are environmental concerns. There are a number of issues, but there is potential there to make some really effective use of digital and AI to enhance our capacity. So, I''m keen—and we''ve had conversations about this already—for that to be an element of the digital enablement of the civil service more generally, let alone legislation.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2804&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.558009', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770432', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3e0fe50107c29a4d9635', 'consultation', 'Senedd — committee consultation', 'Welsh Government Draft Budget 2027-28', 'Welsh Government Draft Budget 2027-28

This is an open Senedd consultation. Responding puts NRLA''s position formally on the record.

Welsh Government Draft Budget 2027-28, start date: Fri, 31 Jul 2026 00:00:00 GMT, end date: Fri, 25 Sep 2026 23:59:00 GMT

Closing date: 25 September 2026.', 'https://business.senedd.wales/mgConsultationDisplay.aspx?ID=632', '2026-07-31', '', '', '', '', '', 'Senedd committee', '', '', '', '2026-09-25', 161.0, 'Critical', 'immediate', 'fiscal_and_legislative_context', 'Context', 'NRLA named', 'Consultation open', 'closing date; consultation; draft budget', 1, '2026-08-24T07:35:33.145471', 'https://business.senedd.wales/mgRss.aspx?f=76', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3eb97b46f43c0a339f2e', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you for the question, and I''m pleased that we do agree that we need to look seriously at ''Future Wales'', namely the national plan, the top-tier plan on developments in Wales. It''s under that, of course, that ''Planning Policy Wales'' lies. So, we need to do the work on that highest level around the national spatial strategy and to include in that the current priorities for growth, infrastructure and regional development and transport. So, it does have statutory status, and I''m very eager, as the work has started to look at that highest level, to then see what needs to be changed in terms of the planning policies, including energy policy, electrification and new electrical lines, and so forth. So, I can assure you that that work is happening.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4926&l=en', NULL, 60.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister', '', 'Future Wales; Planning Policy Wales; planning policy', 0, '2026-08-04T14:03:05.168591', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768159', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3f2cd773c44937585d05', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, well, that is the challenge, isn''t it? What we can do within devolved powers we will do, but we''re very beholden, I think, to those reserved responsibilities of the UK Government.

 Work is ongoing across Government on carbon budget 3. Obviously, the deadline is the end of this year. The UK Climate Change Committee has made it clear that much of the heavy lifting depends on that action from the UK Government, predominantly because industry and energy in the main are non-devolved. So, action in those spaces is really key if we are to meet the carbon budget 3. But we''re doing everything we can within those areas of responsibility that we have, predominantly, of course, around transport and housing, which are the two main sectors that can contribute to this. And, as I say, that work is ongoing and we will be making an announcement later on this year to outline those actions specifically.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4325&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.852429', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771795', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3f383329b1d810d24f20', 'committee_transcript', 'Petitions Committee', '2. Updates - Petitions referred to the Seventh Senedd', 'Thank you very much, Chair. This petition was discussed in the last meeting of the previous Petitions Committee. I noted that Joel James MS had said he would leave us a prod for us to consider it in this Senedd term—so he can consider us successfully prodded to do so.

 It touches on an issue that the previous committee had considered with a few different landfill sites, but this one in particular has been ongoing for a number of years. Our predecessor committee felt that there was still a lot to be done on this particular petition, even though they''d had a response from the former Deputy First Minister, whose portfolio this fell into. Our predecessor committee agreed to refer it on to us, with a view that we might perhaps like to highlight it with the relevant policy committee and pursue the appropriate Minister with responsibility for landfill operations on all these issues around forever chemicals, water quality and odours.

 So, I think there''s one course of action that I would like to suggest for us, which is to take it up, first of all, with the new Climate Change, Environment, Sustainability and Rural Affairs Committee. We could ask them to pursue the matters raised by the petition with the Cabinet Minister for Rural Resilience and Sustainability, and I think it would be appropriate for us to do that because I know that committee is looking to bring that Minister in for general scrutiny as soon as possible. That committee is also looking at its forward work plans, so all of these issues around landfill, water pollution and the air quality issues could be something that the committee might wish to consider more broadly, as well as taking up directly with the Minister.', 'https://record.senedd.wales/Committee/16175', '2026-07-09', 'Vikki Howells', '', '5107', '', '', 'Petitions Committee', '2. Updates - Petitions referred to the Seventh Senedd', '16175', 'http://www.senedd.tv/en/16175?startPos=801&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-08-04T14:03:13.263366', 'https://record.senedd.wales/XMLExport/Download?meetingID=16175&xmlDownloadType=EnglishTranscript#767266', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3f48ebf29c69963ceb8b', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. To return to your point on the Cladiators, yes, I had a very constructive meeting with them on Monday. I was delighted to meet with them and to hear their concerns directly from them.

 I made a written statement on Monday that confirmed the 20,000 social homes that are desperately needed in Wales, for everyone living in Wales. The way that social housing is allocated is a matter for local authorities. Local authorities have a housing register and homes are allocated according to need, and that''s how it should be too. Therefore, I look forward to the work now of supplying more social homes. That''s what''s at the heart of the problem; the core of the housing crisis in Wales is that we don''t have enough social homes. The supply isn''t adequate to meet demand, and that is where we should be focusing our efforts always.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4017&l=en', NULL, 93.5, 'High', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Sector bodies; Housing minister', '', 'social homes; social housing', 0, '2026-08-04T14:03:05.069546', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768148', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3f7d54b8265484cd5a4b', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Thank you. Minister, I was particularly taken when I went up to Llangynidr by the scale of the fire that was up there. In a Welsh sense, it was huge. I appreciate on an international scale it was relatively modest, but it was huge in relation to a Welsh fire, and two things struck me. I met Brian and Julian, Julian being one of the graziers there, and he was saying that the number of sheep that grazed that particular common had gone down from 5,000 to 2,500, and so the fuel that was there to power the fire, obviously, is enormous. And the other thing that struck me was the firebreaks that, under the direction of the fire service, they''d had to put in overnight to try and stem the flow of the fire. On the firebreaks, just looking at it—and I can understand why—they had to go down to the rock. I can imagine in peacetime, if you like, when there''s no fire, you engaging with NRW as a grazier, or as someone who uses that common, you''d be locked up for a decade or more trying to persuade them of the merits of putting that firebreak in. Would you agree that on firebreaks and managing the commons and open spaces, there needs to be a rethink of the ground rules that allow these firebreaks to be put in, so that we are having management tools in place that reflect the conditions we now have with the climate change that we''re seeing? And on grazing, would you agree with me that there does need to be a more balanced approach to allowing stock to graze these open spaces and try and reintroduce grazing to take down that fuel stock that grows on those open spaces that powers these fires?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=774&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.379389', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771783', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3f91bf1318e9df14fec3', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much, and I welcome the opportunity to appear before the committee this morning. I think there is very important work to be done within this portfolio.

 So, to speak specifically about child poverty, as somebody who used to be a member of this committee, I know that some Members will remember our scrutiny of the draft child poverty strategy of the previous Government, and then also our analysis and scrutiny of the current strategy. I''m very clear that that strategy isn''t fit for purpose, if we truly are to see change, the change that we need to see in terms of poverty rates amongst children, and more importantly, perhaps, the impact of that poverty on our youngest generations and on the future of our nation, ultimately.

 So, I am already working on the new strategy. I am drawing upon the evidence that was gathered to draw up the previous strategy, and a lot of the evidence that this committee''s predecessor committee heard in that area. So, evidence from families, evidence from organisations, from stakeholders and others, and from families over the past four years as the previous strategy was formulated, to ensure that the new strategy focuses very closely on what is important to them, and the kind of support that could assist them as they feel the impacts of poverty, but also to see how we can support them to be lifted out of poverty.

 So, with regard to the work that I''ve done, I''ve met with the external tackling poverty group, which includes organisations such as Children in Wales, Save the Children Wales, the Child Poverty Action Group, Citizens Advice, and so on. And the experts, the policy experts, are working to help us to ensure that the new strategy and the targets—I feel very strongly that we need targets and milestones along the journey—to ensure that they are fit for purpose. So, that work is being done.

 I hope to consult, then, on the new strategy and the targets early in the new year. We''ve been very clear, as a Government, in terms of what our priorities are in order to target our efforts at those policies that will have the greatest impact on people in Wales, and children living in poverty in particular. So, of course, that strategy will help us to focus our work in that regard.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=137&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.573325', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771148', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3f9556af65396cbc58e2', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'It''s not in our gift to do that, I''m afraid.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6423&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.170301', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772127', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('3ffbb8c46d4a5cd54848', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you, that''s great. So, there are several topics that we''ll be covering today. We''ll start with child poverty first. For the first question, I wondered if you could give some insight into the progress when it comes to the new child poverty strategy and the key ways in which the Deputy First Minister envisaged how it will be different from previous Welsh Government strategies as well.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=111&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.569551', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771147', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('404d1952624785223592', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'I''m not sure whether I will always welcome a question from Andrew R.T. Davies as Cabinet Minister for Finance, but today in particular, it was particularly useful for me to see that your question, constructed in this manner, allowed me to outline some of my thoughts on how I see the future of budget discussions. And, yes, we are keen, as the First Minister has said, to have discussions with all political parties. We are very conscious of the fact that we are a minority Government. If that supplementary budget vote was useful in anything, it was useful in reminding us, as a Government, that we need to command a majority to pass any budget in this place.

 So, I look to all Members here to consider our roles in a different way perhaps to how we have considered our roles and participation in budgets of the past. In fact, the Welsh Conservatives have an advantage over all other political parties here. You''re almost the continuity party in this Senedd, because you are an opposition party and you''ve played—[Interruption.] You''re consistently an opposition party; I do not prejudge the future. But Reform is a new party in this Senedd, Labour is a party in opposition for the first time and Plaid Cymru is a party in Government, and there are new roles for all of us to play in that. But I hope that as we continue discussions over the next few weeks and months—. And those discussions are happening, and I want now to use pace and to think about how we can have those discussions across political parties and individuals in this Chamber to bring ideas into this big melting pot that is the annual budget. So, I hope that we can do that in a more meaningful way than we have done coming out of the election before the summer. And I think that''s a challenge that all of us have to rise to, and me, in particular, as the finance Minister.', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Elin Jones', '', '162', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=2982&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-09-19T12:39:16.921724', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769536', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('40665fa746a8cc7a5386', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'I agree with your last point, Darren. What I don''t agree with is describing Plaid Cymru as a left-wing party.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Mike Hedges', '', '332', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24343&l=en', NULL, 44.0, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'Opposition housing leads', '', 'supplementary budget', 0, '2026-08-04T14:03:10.628722', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767895', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('40d24f6bc691e1cf0af5', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I know very, very well the challenges faced by Bangor high street. It was my high street growing up, and I''m determined that when we look at Bangor, and all the other high streets throughout Wales, we have a clear focus on using all the tools at our disposal to support them. The town-centre taskforce, I remind him, is for all high streets. There has been specific assistance, to the tune of over £600,000, announced for Bangor in recent months, and I don''t imagine that that is something that the people of Bangor are unhappy about. But it''s always part of a range of measures that we can take as a Government. That announcement today of the 30 per cent cut in business rates is determinedly targeted at helping high streets like Bangor, through supporting those businesses that bring vibrancy, that bring life to those high streets. This is a Government from the get-go that is showing that we are determined to act on the promises that we made, and Bangor, like many other towns the length and breadth of Wales, will benefit from that.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=504&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-19T12:39:24.899070', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768987', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('40e092e444c120b3c4a3', 'legislation', 'Acts of Senedd Cymru', 'Visitor Accommodation (Register and Levy) Etc. (Wales) Act 2025', 'Visitor Accommodation (Register and Levy) Etc. (Wales) Act 2025', 'https://www.legislation.gov.uk/asc/2025/5/2025-09-19/data.xml', '2026-05-06', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 84.5, 'Medium', 'digest', 'second_homes_and_short_term_lets; named_welsh_legislation', 'Context; Planning & place', '', '', 'Visitor Accommodation (Register and Levy); visitor accommodation', 0, '2026-08-04T14:04:14.614021', 'https://www.legislation.gov.uk/asc/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('410ab42262c4c3cb708b', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. So, Hawliau i Gymru is our programme for developing and testing options for strengthening human rights in Wales. It brings together an expert group, therefore a group of people who are legal experts, academics, practitioners. We also have a wider network of stakeholders who have an interest in strengthening human rights in Wales. The work of this group is also to look at lessons from other jurisdictions, to see how other places in the world have approached this. But what I am interested in doing is developing a Welsh model that is ambitious, but that is also practicable.

 So, that work is starting this week, because tomorrow, as it happens, I will be chairing a round-table discussion related to—. The people in that meeting will be officials from other Governments, and also academics from across the United Kingdom and also the Channel Islands, where they''ve started thinking about legislation in this policy area. So, what I hear from that meeting will then feed into the first meeting of the panel that I will be co-chairing next week.

 So, I am going to be announcing the membership of that panel. Once we have made—. We are currently in the process of appointing the panel, so I''m sure you''ll appreciate that there are processes that have to be followed in terms of those appointments, but the process has long since started. But as I was saying, the membership of that group has been designed around what we want this work, this Bill, to deliver, thinking about human rights, thinking about devolution, thinking about the Welsh legislative landscape, thinking about the relative experience, thinking about the perspective of public services and how we can deliver change.

 So, this is a complex job of work. It is going to take some time to do, but the programme for government has committed to bringing forward a proposal for what this Bill, possibly, what this legislation, will look like before the end of the term, clearly. But it won''t be in the first tranche of legislation that we as a Government would want to pass, because we do want to ensure that this is done right, and we want to ensure that it is all something that is fit for purpose and within our competence as a Government.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2624&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee; programme for government', 0, '2026-09-25T06:30:35.854747', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771214', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('415551df5e97dcd1ebde', 'calendar', 'Senedd forward look', 'Local Government, Housing and Planning Committee — 01 October 2026, 09.30', 'Local Government, Housing and Planning Committee is scheduled to meet on 01 October 2026 at 09.30.
Meeting status: Confirmed; Hybrid
This is an opportunity to influence: committee papers and any call for written evidence are normally published in the two weeks beforehand.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=987&MId=16305', '2026-10-01', '', '', '', '', '', 'Local Government, Housing and Planning Committee', '', '16305', '', '2026-10-01', 48.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; written evidence', 0, '2026-08-07T07:54:11.953652', 'https://business.senedd.wales/mgWebService.asmx#GetAllMeetingsByDate', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('41a34880d2050a50147b', 'plenary_transcript', 'Plenary', '5. Statement by the Deputy First Minister and Cabinet Minister for Social Justice and Equality: Update on Early Years Childcare and Play', 'In the first point, really, you were querying about the midpoint, and I think I''ve tried to explain. I think we said in our manifesto it was going to be around £400 million additional, so what we''re seeing as the midpoint—that was modelled on a midpoint as well. It’s the common practice. So, the midpoint that we''ve modelled here is £375 million. But as I said, obviously—because this is demand-led, this is a new thing—we''re hoping that all the discussion around childcare will make sure—. And the point you made around simplifying the process too—we know that many people don''t take up childcare, not only because it''s disjointed, but because it''s difficult, it''s complex and there are so many different eligibility thresholds, things you''ve got to apply for at different points during your child''s life. So, I can assure you that the point around simplification and what that looks like, what that front door looks like, is absolutely part of this work as well. And my officials are already working on that. So, it isn''t higher, actually; it''s around the same as what we projected, but we do recognise, of course, that there are all kinds of variables as we push forward towards the next phases that we need to allow for. But I do welcome your support for this initiative, for this policy, and, as I said, I agree absolutely on your point around simplifying the system.

 On your point around the way this policy interacts with other policy areas, it does, obviously, around education. Part of this work is about—. We''ve seen, haven''t we, it''s been exacerbated since COVID, but we''ve seen for a long time that families do need more support in order to make sure that their children are ready to learn, and this is going to play a big part in that. So, I''m having conversations—I actually met yesterday again with the Cabinet Minister for Education and the Welsh Language. We are working on how we can measure that, how we can evaluate the effect that this will have on that readiness to learn while keeping that absolutely child-centred, that evaluation. So, it will interact across Government and, as I said, especially with health, the interventions, the team around the family, and that support we will absolutely retain, but in a different form as we roll out this universal system.

 You asked me about exactly how the additional funding from the supplementary budget was going to be utilised. We''ve said that we''re going to invest an additional £55 million in the additional budget. So, hopefully, if you support this policy, you can support that budget this afternoon. Twenty million pounds of that will help to accelerate the roll-out, so that''s the work we''ve indicated to local authorities that they''re able to utilise in order to make sure that we get to the point where funded childcare is available to all two-year-olds in Wales by the end of this financial year. Then there''s £10 million of capital funding, which is going to help enhance and expand childcare settings, improving quality and capacity and accessibility of early years provision. And then £25 million of that is going to be used to support the wider system, including managing rising demand, because we''re talking about it a lot more now—it''s been such a front-and-centre policy during the election. People are coming to access more provision, which is great. We need to make it easier for them and more affordable for them. We want to strengthen the long-term sustainability of providers, and that''s something you talked about as well. And that is something that is absolutely crucial as well, and, again, is part of the work that we''re doing. So, we''re already investing in that, and, of course, supporting Welsh-medium childcare is part of that as well.

 So, on the last point on safeguarding, I think it is a really important point, and quality, you know, with the national minimum standard, which was updated last month. Wales has the highest national standards issued under the Children and Families (Wales) Measure 2010, and the Child Minding and Day Care (Wales) Regulations 2010, and Care Inspectorate Wales, of course is a regulatory body, so we will always make sure that anyone who is registered for providing day care and child minding will be inspected according to those regulations.

 We are looking at creative solutions. You know, I think we really need to consider child minders in this, who are constantly coming up as ''excellent'' and ''good'' when they''re inspected. They provide such a valuable service for people who work irregular hours, especially in places where there isn''t a density of population. So, we will absolutely be considering other models of provision as we roll this out.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Sioned Williams', '', '8670', '', '', 'Plenary', '5. Statement by the Deputy First Minister and Cabinet Minister for Social Justice and Equality: Update on Early Years Childcare and Play', '16085', 'http://www.senedd.tv/en/16085?startPos=13204&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:09.462920', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767807', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('41a56288c2e386eca9fe', 'press_release', 'Welsh Government — Announcement', '30% business rates cut for high street hospitality and leisure venues', '30% business rates cut for high street hospitality and leisure venues
Wealth of venues across Wales to see business rates cut by 30% from 1 April 2027. Small and medium-sized businesses with a rateable value below £51,000 to benefit with change fully funded. First Minister: This gives businesses “the confidence to invest, grow and keep serving the communities that rely on them.”

Wealth of venues across Wales to see business rates cut by 30% from 1 April 2027. Small and medium-sized businesses with a rateable value below £51,000 to benefit with change fully funded. First Minister: This gives businesses “the confidence to invest, grow and keep serving the communities that rely on them.”

Pubs, restaurants, cafés, bars, licensed clubs, hotels, gyms, cinemas and other high street favourites across Wales are set to see their rates bills cut by 30% as the Welsh Government backs the businesses people depend on.
The move forms part of the Welsh Government’s manifesto commitment to rebalance business rates and breathe new life into town centres.
This permanent support will exceed the 15% temporary relief for food and drink hospitality currently in place, giving businesses greater certainty to plan and invest for the future.
Businesses set to benefit include:
food and drink hospitality venues: pubs, restaurants, cafés, bars, food courts, licensed clubs and live music venues
visitor accommodation: hotels, guest houses and hostels
leisure venues: cinemas, theatres, libraries, museums and gyms
Eligible small to medium sized properties with a rateable value below £51,000 will attract the permanent support. Retail shops will also continue to benefit from this support, which will build on the lower multiplier in place this year.
A small increase to the higher multiplier, which applies to the highest-value properties in Wales, will fund the support, without reducing the overall contribution business rates make to funding public services in Wales.
First Minister Rhun ap Iorwerth said:
"Our high streets are the heartbeat of communities right across Wales, and the businesses that fill them deserve our backing.
“This 30% cut to rates for pubs, cafés, gyms, hotels and so many other local favourites is about giving those businesses the confidence to invest, grow and keep serving the communities that rely on them.
“We’re making the system work better for the sectors that bring our town centres to life."
The change sits alongside the work of the Town Centres Taskforce, which will consider what more tailored support individual town centres need, recognising that different parts of Wales face different challenges.
Cabinet Minister for Finance Elin Jones said:
"This significant and permanent change will make a real difference to eligible hospitality and leisure businesses right across Wales.
“We''ve taken a balanced approach, ensuring this support is affordable while protecting the vital contribution business rates make to our public services – targeting help where it will have the greatest impact on our high streets."
Regulations will be brought forward in the autumn and, subject to Senedd approval, will take effect from 1 April 2027.
The precise values of all multipliers for 2027-28 will be confirmed as part of budget preparations, following the UK Government''s Autumn Budget.', 'https://media.service.gov.wales/news/30-percent-business-rates-cut-for-high-street-hospitality-and-leisure-venues', '2026-09-15', '', '', '', '', '', 'Welsh Government', 'First Minister; Finance; First Minister - Rhun ap Iorwerth; Cabinet Minister for Finance - Elin Jones', '', '', NULL, 81.0, 'Medium', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', 'First Minister / Cabinet', '', 'business rates; visitor accommodation', 0, '2026-09-15T12:01:02.171113', 'newsroom:30-percent-business-rates-cut-for-high-street-hospitality-and-leisure-venues', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('421a4fe196adeb23ab2d', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think, in that particular example, in terms of university students, university students are eligible to register in two places. I think what we''re concerned about is that if you are using university data to automatically register students, is the unintended risk—well, they can be registered twice; they can''t vote at the same election twice—of them unintentionally being in a position where they could do that and not understand the consequences through automatic registration. While it''s correct that they can be registered in both places and that could possibly be the case, I think our concern would be more what Sandra alluded to earlier, that because of the nature of the way that names are on different sorts of documentation and things, and different council records, there''s the ability to almost register the same person twice because of differentiations within their name. There''s a risk of that because you haven''t necessarily got the additional information that can uniquely identify somebody, such as a national insurance number or a date of birth, within local government records. So, using local data, there is a risk of duplication.

 I think we referenced in our written evidence that the Democracy Club, who administer polling station staff, and Financial Data Intelligence Framework, who have huge expertise in data—far better than I definitely do—have explained some of these things. They''ve got huge concerns over the nature of fuzzy matches, which then naturally lead to potential for duplications. You''ve got the manual checks that kind of mitigate some of that, but, again, without additional information that some national data sets, for instance, would potentially have, for you to be certain that it is a unique, different person, or that it''s the same person—. That''s more our concern, I think, in terms of duplications.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5445&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; written evidence', 0, '2026-09-18T11:33:49.426534', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#770004', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('429a5461fbd26fa7d616', 'committee_transcript', 'Legislation Committee', '1. Motion to elect a temporary Chair under Standing Order 17.22 for this meeting', 'Thank you. Are there any other nominations? I see that there are none. I therefore propose that Peredur Owen Griffiths is appointed temporary Chair of the committee for today''s meeting. Are there are any objections? I see that there are none. I invite Peredur to take the chair.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Sarah Sargent', '', '', '', '', 'Legislation Committee', '1. Motion to elect a temporary Chair under Standing Order 17.22 for this meeting', '16254', 'http://www.senedd.tv/en/16254?startPos=40&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.043876', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770420', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('429f50288a04f6f4a737', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. That wider food resilience piece is important to us. It''s a feature of the work that''s already started around the national food strategy as well. Ensuring access to affordable food is important. Now, much of that comes back to, I would say, producing more of it ourselves, making sure that we have that food resilience as a priority in terms of what we''re asking farmers and land managers to achieve. But it also means protecting local processing capacity as well, so that we retain the economic benefits and create jobs as best we can as part of that process. So, that opens a whole other sphere of discussion.

 You''ll be aware that the Deputy First Minister as well, last week, or earlier this week, announced £5 million for local authorities in Wales to try and support interventions around poverty, and food particularly. And I was very glad that she implemented or took consideration of rurality in the way that that was distributed, which, again, I hope speaks to a different way of looking at these things from the Welsh Government. 

 So, there''s a lot to do, and we are getting on with it, but, certainly, that''s another one.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2406&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.643629', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771938', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('42adbd2b11b339f04ced', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'That is an excellent question, if I may say so, because, in a Parliament without a majority, it is inevitable that the Government has to consider whether it will be possible to try and get the agreement of the Senedd to new legislation. As we have heard, there is very significant work happening on legislation, and therefore it would be very unwise, and, if I may say, quite ineffective, to spend quite a bit of time on legislation when there is no hope of that legislation passing. So, we have been looking at the legislative programme through that lens.

 We could look at different elements of that programme. There are Acts that make the statute book more clear—that is, that codify it and draw issues together. I would hope that the Senedd as a whole would look at such Acts, that don''t change policy but rather draw stuff together in a way that is accessible and open. I would hope that the Senedd as a whole would look kindly on those kinds of Acts. There are very specific pieces of legislation. Possibly, we will come on to the proposed Act in a very specific sphere, the wildlife sphere, where again I would expect to achieve an element of consensus across the Senedd.

 And then, there are other Acts, for example, around housing, on developing the renters'' support programme. One might look across the Senedd and see that similar provisions were included in the manifestos of at least four parties, if not more than that. So, we are looking at these kinds of things. It is possible, as the collaboration develops in this place, that we will also see specific proposals being laid on the table by the opposition parties and that the Government might decide to work together on such issues. So, we are a Government that is open-minded and we are a Government that recognises and acknowledges very clearly the arithmetic of the Senedd. I think that''s important, and it''s important that this committee and the Senedd as a whole understand that.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1583&l=en', NULL, 120.7, 'High', 'digest', 'private_rented_sector; fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system; Private rented sector', 'First Minister / Cabinet', '', 'Legislation Committee; legislative programme; renters', 0, '2026-09-22T11:55:09.313948', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770406', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('42beae070682fcd3a085', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch. Laura Anne Jones.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=3196&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.908683', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771170', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('42f456b5a4875c323226', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'I think, in terms of the second point on flexibility, not to say there''d be flexibility in the number of days per se, but there are processes by which you could be removed from the register after that point. So, in that situation, that would be something that could happen.

 In terms of the Royal Mail concerns, I think it''s a fair point. We might need to come back to the committee on that, if that''s okay, or maybe it''s a question you could pose to the Welsh Government, in terms of what some of those delays are looking like on the ground at the moment and how that would come up against a 28-day period—unless you had anything to add on that, Tom.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Davies', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1375&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.893927', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769872', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('434249d475f6798b7475', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'With five minutes to go, I just thought I''d bring Adrian in with some questions as well, just to finish off.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4950&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.983761', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770509', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4354801f558bc3928ad5', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Paul.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3606&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.829700', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771819', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4354b5e9a0e7aeb724a6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Oh, yes, on British Sign Language.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4953&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.065641', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771306', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('43dd6cf417f0e27c954f', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think our experience is, from what we''ve heard from electoral administrators, is that a lot of them are struggling to get even access to council tax data in their authorities at the moment. So, while there are provisions there, as we said earlier, that allow them to have access to that, there are definitely difficulties in getting the relevant other teams in the council to provide the information and to provide it on the frequency of the basis, particularly in those sorts of circumstances, for them to actually have that. I don''t know whether, Sandra, your experiences are—', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Clare Sim', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5357&l=en', NULL, 109.2, 'High', 'digest', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; evidence session', 0, '2026-09-18T11:33:49.406711', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769988', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('43e7a83cd44cf59b8b02', 'consultation', 'Senedd — committee consultation', 'Priorities Consultation: Equality, Human Rights and Social Justice Committee', 'Priorities Consultation: Equality, Human Rights and Social Justice Committee

This is an open Senedd consultation. Responding puts NRLA''s position formally on the record.

Priorities Consultation: Equality, Human Rights and Social Justice Committee, start date: Thu, 23 Jul 2026 00:00:00 GMT, end date: Fri, 18 Sep 2026 23:59:00 GMT

Priorities Consultation: Equality, Human Rights and Social Justice Committee Priorities Consultation: Equality, Human Rights and Social Justice Committee View the background to this consultation View all current consultations Purpose of the consultation The Equality, Human Rights and Social Justice Committee has been set up by the Senedd to look at policy and legislation, and to hold the Welsh Government to account on specific issues. This includes equality and human rights, fair work, community cohesion and safety, tackling poverty, and social justice. In addition, the Committee may investigate any area of policy from the perspective of equality and human rights. During the autumn 2026, the Committee will be considering its strategic approach, objectives and ways of working. We would like to invite you to share your views on what you consider the Committee’s priorities for the Seventh Senedd should be. To submit your views, please complete the online form . The Committee are keen to hear from as many people and organisations as possible. If you would like to submit your views but do not want/are not able to complete the online form, please contact the Committee at SeneddEquality@Senedd.Wales and the Committee’s clerks can arrange with you a different way for your voice to be heard. The Committee’s postal address and telephone number can be found at the end of the consultation page. The closing date for submissions is Friday 18 September 2026 . Providing Written Evidence The Senedd has two official languages, Welsh and English. In line with the Senedd’s Official Languages Scheme , the Committee welcomes contributions in both or either of our official languages, and we ask organisations that are subject to Welsh Language standards or schemes to respond in line with their own obligations. Please inform the Committee when submitting responses if you intend to provide a translation at a later date. Please see guidance for those providing evidence for committees . Disclosure of information Please ensure that you have considered the Senedd’s policy on disclosure of information before submitting information to the Committee. Contact details Should you wish to speak to someone regarding this consultation, please use the below contact details: Equality, Human Rights and Social Justice Committee Welsh Parliament Cardiff Bay Cardiff CF99 1SN Email: SeneddEquality@senedd.wales Telephone: 0300 200 6565 Topics Helpful Links Find a Member of the Senedd chevron_right Sign

Closing date: 18 September 2026.', 'https://business.senedd.wales/mgConsultationDisplay.aspx?ID=631', '2026-07-23', '', '', '', '', '', 'Senedd committee', '', '', '', '2026-09-18', 224.0, 'Critical', 'immediate', 'committee_scrutiny', 'Housing system', 'NRLA named', 'Consultation open; Opportunity to influence', 'Equality, Human Rights and Social Justice Committee; closing date; consultation; consultations; written evidence', 1, '2026-08-04T14:02:42.866340', 'https://business.senedd.wales/mgRss.aspx?f=76', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('443f4eb68b474584fd5f', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'That''s an option. Certainly, I''d be open to considering that. There''s a logistical challenge in terms of getting that money out the door in a timely fashion, because setting up a scheme and administering it isn''t something that you do by pressing a button. But, certainly, I''m happy to consider that. I''m aware as well of calls for a UK-wide emergency scheme, which is something I would really be supportive of, something I would like to see happen. So, there are a few potential elements there. 

 I''ll come back as well to the point I made earlier—it isn''t always about money. There are other things that Government can do that can support the industry in difficult times. You''re aware that, due to the weather circumstances, farmers are now going later into the autumn for silage cuts, hence one of the reasons we felt that limiting the closed period would help. So, there are practical interventions that we can make as well. But, certainly, in terms of funding, where we can support, we will. It''s just a matter of which means is best to achieve that and how affordable that is, but also how practical it is in terms of the way that we implement it.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2585&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.667540', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772077', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44560bd7c77f51efdb7d', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'Thank you for the question. Of course, Antoniazzi''s is a well-established business of almost 100 years'' standing. What we will see outlined by the Cabinet Minister for Finance this afternoon will be truly significant. SMEs are the backbone of our economy, and we''ve made it clear, particularly through the Cabinet Minister for Enterprise, Connectivity and Energy, that we are determined to support and grow indigenous Welsh businesses and to ensure that successful businesses continue in Welsh ownership, giving them the confidence to invest in their future. The changes to non-domestic rates will be introduced as soon as possible, from the beginning of next year or the next financial year. They will be permanent, which, again, is a step that gives business confidence. I look forward to hearing the details from the Minister later this afternoon.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=614&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:24.916248', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768973', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4470b8eca03e4afcbb0a', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Well, it''s one of our policy areas that we feel very strongly about, quite clearly. We would like to see a statutory basis for the Sewel convention, in a perfect world. Meantime, a well-worded, strong memorandum of understanding is required, in our view. I have not had discussions, but I know the First Minister has had discussions, and my colleagues had discussions, and it''s something that we are raising even now. There''s a discussion on the memorandum of understanding. It is, as the Member obviously recognises, vitally important. For far too long, it has been mistreated, or, should I say, disrespected, perhaps. It''s something that is core to getting good government, and it''s something that our colleagues in Scotland feel equally strongly about. I''m sure that my colleague can address that, because he''s been in discussion there as well. So, to reassure the Member, there is an ongoing dialogue now about this issue. As I''ve said, we would like to see statutory underpinning, but, meantime, we would be in favour of a strongly worded, fully understood memorandum of understanding that is respected by all.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4017&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.790026', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770460', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44a7693f75eb45707cbb', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Because I need to prepare for that one.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6808&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.282266', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771258', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('44ab2c9392a98a902acd', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'That''s fine.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6806&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.280754', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771257', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('455bfdaa413b411135ce', 'research', 'Senedd Research', 'The cost of living: Ongoing pressures and recent developments', 'The cost of living: Ongoing pressures and recent developments

As with other parts of the UK, people across Wales have been hit by a living standards squeeze since the 2008 financial crisis, which has been exacerbated over recent years by cost of living pressures. As highlighted by the Institute for Fiscal Studies , median household incomes in Wales have increased by “just 0.7% per year” in real terms since the early 2010s, which includes a decrease in the first part of the 2020s.

Over recent months, we’ve seen further energy and fuel price rises as a result of the Iran conflict, with predictions of further increases in January 2027 from Money Saving Expert and Cornwall Insight . The Centre for Economic and Business Research (CEBR) predicts higher inflation and lower wages due to the Iran conflict will reduce the real value of average UK household incomes by £1,100 in 2026 and £1,300 in 2027.

The First Minister has said helping households with cost of living pressures is a “core mission” of the Welsh Government. Our article explores what the data tells us about living standards and cost of living pressures, what actions the Welsh and UK governments are taking to support households, and what further action may be needed.

Households’ living standards have been squeezed since the 2008 financial crisis, with sluggish productivity growth a key factor in this.

Wales has consistently had lower wages and Gross Disposable Household Income (GDHI) then the UK average, which is closely tied to our lower productivity levels , although there are other factors . As the Welsh Government has outlined , most parts of the UK have seen a decline in GDHI per head compared to the UK average over the longer term, with the exception of London, which has seen a considerable increase.

The Office for National Statistics describes Gross Domestic Household Income (GDHI) as the amount of money that households and people living in communal establishments have to spend or save after paying taxes and/or receiving benefits. It also includes the business income of self-employed people.

Figure 1: Gross Disposable Household Income per head as a % of the UK average for devolved nations and selected English regions, 1999-2024

Source: Office for National Statistics, Regional gross disposable household income, UK: 1997 to 2024

Over recent years, the rising cost of living has added to the challenges Welsh households face. The Resolution Foundation says in its latest living standards outlook that, “although weak growth in wages and other sources of income are the key drivers of stagnating living standards, high inflation has compounded these pressures”. While inflation is considerably lower than its peak in 2022, UK consumer prices in 2026 are over 30% higher than at the start of 2021 .

The cost of essentials has risen considerably over recent years. When the next energy price cap increase takes effect at the start of October, a typical household’s energy bill will have risen by 58% since winter 2021 . The Food and Drink Federation notes food prices have increased by nearly 40% since 2020 , with further predicted rises meaning that a £100 weekly shop in 2020 is likely to cost nearly £150 by summer 2027. Office for National Statistics figures show that private rents in Wales have risen by 38% since mid-2021, a greater increase than in England and Scotland.

The Resolution Foundation found that , between 2019 and 2025, inflation disproportionately affected the poorest households, who spend more of their income on essentials. This has reduced their living standards by more than 3% relative to the richest households. Recent analysis from Citizens Advice Cymru highlights the practical impacts of cost of living pressures on lower-income households. Across Wales, 30% of households sometimes don’t have enough money to pay for essentials, 31% of people have cut back on energy use, and 6% of people have a negative budget as the cost of essentials is higher than their income. Oxfam Cymru has described the impacts of cost of living pressures as “deeper poverty, growing reliance on food banks and crisis support, and rising demand on already stretched public services”.

Both governments operate a range of schemes that support households with the cost of living . Key Welsh Government cost of living initiatives include emergency support such as the Discretionary Assistance Fund , emergency food aid , help through the Warm Homes Programme with energy advice and home energy efficiency improvements, and a £200 grant to help eligible off-grid households with rising energy costs.

The UK Government also provides a range of cost of living support , some of which is available to households in Wales. Shortly after taking office, the Prime Minister announced a number of new cost of living policies to “give families and business owners breathing space”, including cutting VAT on domestic electricity bills . He said that any decisions around longer-term measures will be taken in the UK Government’s Budget, on 28 October.

Given the budget constraints the Welsh Government says it faces , the National Institute of Economic and Social Research has suggested it should focus any additional cost of living support on the poorest households . Similarly, the Resolution Foundation and Energy UK have called for any additional UK Government support with energy bills this winter to be targeted at those most in need.', 'https://research.senedd.wales/research-articles/the-cost-of-living-ongoing-pressures-and-recent-developments/', NULL, '', '', '', '', '', 'Senedd Research', '', '', '', NULL, 90.0, 'High', 'digest', 'energy_efficiency; welfare_and_support', 'Housing system; Property & energy', 'Sector bodies; First Minister / Cabinet', '', 'Warm Homes; discretionary assistance fund', 0, '2026-09-22T11:59:56.158070', 'https://research.senedd.wales/research-articles/', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('455c1685e0b1457375cf', 'plenary_transcript', 'Plenary', '4. Statement by the First Minister: Legislation', 'As the former Chair of the Finance Committee, I reflect on what we were told by former finance Ministers about the fiscal position of the previous Government. I''ve also been following what the new finance Minister has had to say in her analysis of her inherited tight fiscal position, once the actual line-by-line detail has been seen. It also appears that things have got even tighter in recent months as a result of events out of this Government''s control. Nevertheless, it''s good to see that Plaid Cymru''s manifesto commitments are being delivered in this legislative programme this afternoon. I firmly believe that these commitments are for the benefit of the people and communities that we all represent—for example, the community right to buy.

 Not only that, these commitments are in line with the pledges of some of the opposition parties in this Siambr, as we''ve heard this afternoon. I''ve even agreed with one or two things that Darren Millar has said this afternoon, which is quite something. I hope, therefore, that we''re able to put aside some of the political posturing and point scoring in order to find the common ground. So, First Minister, will you agree with me that we should focus on the common ground and those outcomes that benefit people the length and breadth of Wales? Diolch.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Peredur Owen Griffiths', '', '8579', '', '', 'Plenary', '4. Statement by the First Minister: Legislation', '16085', 'http://www.senedd.tv/en/16085?startPos=10277&l=en', NULL, 88.0, 'High', 'digest', 'social_housing; fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; community right to buy; legislative programme; right to buy', 0, '2026-08-04T14:03:09.167489', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767766', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('455e442500fd3f39533f', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Can I just unpack that slightly? Following what Adrian is suggesting and the conversation there, where does this committee—? Well, this is the Legislation Committee, so we would have no role, necessarily, in the scrutiny of that, but for the Senedd as a whole, how does the scrutiny of that decision making and making sure—? Obviously, if legislation is in front of us, we can scrutinise that legislation; if it''s done through other mechanisms, do we need to look at how that scrutiny element is done?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5170&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.027089', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770532', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('459345f6c1a295429013', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, and, of course, the global impacts we can''t do anything about. The Strait of Hormuz and all that will have an effect, and it just underlines, I think, the need for us to be as self-sufficient and resilient as possible, and that goes for meat and horticulture as well. We''re woefully underproducing in that space, and both of those are particular areas that have been identified as priority workstreams for the food strategy.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2489&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.653438', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772039', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45bca3f736c27a74d1c8', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'A couple of questions, one on Sewel. I wonder if you could give us any detail you can on discussions that you may have had with UK Government on the Sewel convention. Perhaps you could, in answering that, give us an indication of what progress has been made around agreeing a memorandum of understanding on the Sewel convention.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peter Fox', '', '4787', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3991&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.784362', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770458', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('45f00aaf77b72bef7cca', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Okay, I''m sure you will.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1933&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.546819', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772015', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('460616078689b761d63a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'And then, if I can, Chair, lastly from me. What''s really struck me today is the barriers to accessing data sets, even within one''s own local authority. So, how do you best see that being tackled?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5870&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.499970', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769965', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46065d2cfeb9d2843e95', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes, we''re in the process of developing the timetable, as the Cabinet Minister has outlined. There are lots of different parts to developing a timetable, I''m sure you''ll appreciate. A big part of thinking is ensuring that proper scrutiny time is factored into those timetables, as well, and ensuring that committees don''t become swamped, for example, with particular pieces of legislation. So, it''s a bit of a 3D jigsaw puzzle, but we''re working on that at the moment, and I''m sure, as it firms up, we''ll be able to provide more information. As the Cabinet Minister says, we expect that a tax Bill will likely be one of the first runners. At the moment, nothing is absolutely finalised through the autumn term, but, once things do firm up, I''m sure we''ll be able to share more.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Sophie Brighouse', '', '', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=332&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.092416', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770363', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46279214c93c92d11f6a', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Item 8, legislative consent motion, Steel Industry (Nationalisation) Bill. I call on the Cabinet Minister for Enterprise, Connectivity and Energy to move the motion—Adam Price.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', '16085', 'http://www.senedd.tv/en/16085?startPos=20135&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'Legislative Consent Motion', 0, '2026-08-04T14:03:10.217391', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767871', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('463936ad670504ba6022', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I think that''s a good question. Are we in a position to answer that today? I''m not sure. Of the six key points of Noble, we''re working through each of those. I was pondering to myself whether the most appropriate thing for us to do would be, in 12 months, to update the committee on the progress on each of those. Some of them are clearer than others in terms of how you might demonstrate and measure success.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3226&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.640493', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770415', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('46d003b2b0220930abd6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. We''ll move on to poverty more widely and the cost of living. Steve Bayliss.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1265&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.697122', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771157', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4732361805504d1c66fd', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'No.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1429&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.901281', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769878', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47682430fbace53c5d37', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Reform believes Britain must do everything it can to retain the ability to make its own steel. Our MPs supported this Bill in Westminster, and today we will support it in the Senedd. But, we have to be very clear, this Bill comes far too late. The workers and their families at Port Talbot know that better than anyone. For years, they were promised certainty, instead they got delay. They were promised a plan and, despite the £1.25 billion transition programme, including up to £500 million of taxpayer support, many workers are still asking what replaces the secure skilled jobs that have been lost. Instead of those jobs, they got managed decline. Thanks to praying at the altar of net zero, we all now know that economic decline comes hand in hand with net zero. The blast furnaces have gone, thousands of livelihoods have been affected, and Britain has become more dependent on imported steel as a result.

 More than 2,100 Tata Steel jobs had been lost by September last year, with many of those losses concentrated in and around Port Talbot. Behind every one of those figures is a family, a household and a community that deserved better from its Government. While countries like India and China continue to expand their steel making, forging ahead using a balanced energy mix, what we have is not an industrial strategy that people can rely on, it''s failure on an industrial scale.

 These decisions haven''t affected climate change one bit, or even contributed to solving it. They''ve moved the problem elsewhere, if not, indeed, made it worse by having to ship product around the world and weakening our national resilience. The closure of Port Talbot''s blast furnaces have been linked to almost two thirds of the reduction in UK emissions between 2023 and 2025, yet global emissions do not disappear. When that production moves overseas, they are simply exported along with the jobs. The only achievement here is economic decay and destroying Welsh communities.

 Where intervention is needed to protect steel making, it should be decisive and focused on rebuilding a competitive industry. Our steel workers deserve an industry with a future. Our nation demands a strong steel industry and a Government with a credible strategy, one that protects jobs, strengthens Wales, and secures Britain''s industrial independence. This Bill is a necessary step towards that and it has our support. Diolch.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Jason O''Connell', '', '12158', '', '', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', '16085', 'http://www.senedd.tv/en/16085?startPos=20843&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'Legislative Consent Motion', 0, '2026-08-04T14:03:10.298393', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767863', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47c528f7637745ea6ffa', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'I accept that there is a higher ask of those businesses across the business rates portfolio that have the higher rateable values. The bit you didn''t mention in your question was those up to 20,000 businesses that will benefit from lower taxes as a result of the announcement yesterday and the support for retail premises as well. I think the premise of your question is, though, that this is not just about how we allocate the public funding that''s available to us, but how we also use our taxation system to ensure, yes, that we''re using it to fund public services, because taxation is what enables public services to be run, but also how we get that balance right in terms of supporting our economy. All of those together, again, are part of the considerations when we need to think about where we strike this balance.', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Elin Jones', '', '162', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=3992&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-19T12:39:17.053404', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769547', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47d7bcb2385a0a821fc0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Thank you, Chair.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Peter Fox', '', '4787', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=4955&l=en', NULL, 97.7, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'Opposition housing leads', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.342536', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769944', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('47e4c1b22b6bff68cd5d', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'The fact that I''m now a Minister in Government doesn''t change my values at all. I continue to be a campaigner as well as a Minister in the Welsh Government, and I''m sure that other members of the Cabinet agree with that.

 There is a place for pension funds in Wales to invest responsibly and locally. Of course, although, as you note, we don''t have direct responsibility over pension funds, there are discussions that happen, and we do encourage pension authorities to invest responsibly and ethically, so that public sector pensions contribute positively to the future of Wales—economically, socially and environmentally.

 One excellent use of pension funds is investing in the social housing stock, and you know that I''m campaigning for more social housing. I understand that the city and county of Swansea pension fund has just created a fund worth £51 million that will invest in social housing on a local level. I''m very supportive of that step.

 The Wales Pension Partnership is responsible for explaining how they will invest. That doesn''t mean not investing in the defence industry, for example, but it does mean not investing in companies that produce controversial arms. So, already there is an ethical framework for the Wales Pension Partnership.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=3101&l=en', NULL, 49.5, 'Low', 'dashboard', 'social_housing', 'Housing system', 'Housing minister', '', 'social housing', 0, '2026-08-04T14:03:04.982006', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768082', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('4831bf2bdd76eb9af3a1', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch. Elfed Williams.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6892&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.296224', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771268', NULL, NULL, NULL, NULL);
