INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('68fff87ca651cb53ef0f', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'The clue''s in the name.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=22862&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.459189', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767960', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('691aa67dc55ba400955e', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, anything, but for bluetongue, which is generally throughout. HerdSafe gives an element where you are able to go onto the farms and test the suitability, the safety processes that they go through. And a general process like that, if it was done via technology, could that be a solution on an ongoing basis as a general backdrop?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'John Davies', '', '4650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6697&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.213113', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772116', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('69b65b4db3bf5f7cb7a2', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '—over the past few months. So, I''m just looking for some reassurance, really, that that investment will continue, and particularly for those areas of peatland that have been damaged in the last few months.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Vikki Howells', '', '5107', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=1820&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.528093', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772044', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('69d230af6105620e59ef', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Sure.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1984&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.395271', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770376', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b3110222d6b3fc52a1b', 'written_statement', 'Welsh Government — Written Statement', 'Written Statement: Council Tax Reduction Scheme Annual Report 2025-26', 'Written Statement: Council Tax Reduction Scheme Annual Report 2025-26', 'https://www.gov.wales/written-statement-council-tax-reduction-scheme-annual-report-2025-26?utm_source=rss-announcements&utm_medium=rss-feed&utm_campaign=announcements-Written+Statement%3A+Council+Tax+Reduction+Scheme+Annual+Report+2025-26', '2026-08-14', '', '', '', '', '', 'Welsh Government', '', '', '', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'council tax; council tax reduction scheme', 0, '2026-09-02T11:36:04.872296', 'https://www.gov.wales/announcements/rss', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6b76cb9f5008a47a6997', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'Thank you, Minister.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Kerry Ferguson', 'Deputy Presiding Officer', '12177', '', '', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', '16260', 'http://www.senedd.tv/en/16260?startPos=11395&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:26.283560', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769237', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6baff26ed07425ffe0fc', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Just to give you some context, when we''re talking about the statute book, it is important to bear in mind that the Senedd has inherited that law. So, when the Senedd was created and when decisions were made on what areas were within the Senedd''s competence, when that happened, to all intents and purposes, the statute book in those areas was transferred to be your responsibility or ours. That is important to consider, because just a handful of Wales-only legislation existed. So, there''s a very different history in Wales compared with Scotland, for example, where there was quite a bit more Scottish legislation that had been passed by the UK Parliament.

 So, the reason that I say this in terms of this question is because all of that legislation was in English, of course, and it''s important to consider as well that the legislation that existed for Wales was also English law or was legislation that applied to the rest of the United Kingdom. So, every time we legislate, we have decisions to make on how we legislate, and going right back to when we started this work, I would say that it''s easier, almost without exception, to amend the legislation that already exists—namely to do it in English. That is just easier, and that''s the reality.

 But we decided 15 years and more ago that we wouldn''t do it like that, that we would try and restate as much as we could and create legislation for Wales in particular that was bilingual. Therefore, for example, going back to the law on consent for organ donation, that would have been quite a bit easier to do if we just changed the 2004 UK legislation, but we took out that subject in its entirety, 30 pages—. It was just one small change we were making, of course, just changing the consent, but we took all of that legislation on the subject, all 30 pages of it, and we restated it. I think it was only one page that changed the law, but we created it in the Welsh context and it was bilingual.

 And that''s what we do then by consolidating and codifying the law. Every time we do that, we increase the bilingual legislation that exists. So, it''s just important to understand that context. Thank you.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dylan Hughes', '', '', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4694&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.936196', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770611', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c48213f7e3aaf578f3e', 'research', 'Senedd Research', 'Air Quality and Public Health', 'Air Quality and Public Health

Published 22/07/2026 | Reading Time minutes

Air quality is an important public health issue in Wales. This research briefing examines the main sources of air pollution, how air quality is monitored and regulated, the health effects of pollution, and how pollution levels have changed over time.

Air pollution can be caused by both human activity and natural processes. Major pollutants such as particulate matter, nitrogen oxides, and ozone, are continuously monitored across Wales. The main human sources of air pollution include transport, domestic burning, industry, electricity production, and agriculture.

The burden of poor air quality is equivalent to around 1,000 to 1,400 deaths each year in Wales. A large body of evidence shows that air pollution can cause negative health outcomes, including respiratory and cardiovascular diseases, cancer, adverse pregnancy outcomes, and effects on cognitive health. Exposure and risk are not evenly distributed, with some groups and communities more affected than others. Wider social and economic consequences include pressures on the NHS and the interaction between pollution and existing inequalities.

Action at both the UK and Wales level has sought to limit the production of air pollution and people’s exposure to that pollution. Notable legislative milestones include the Environment Act 1995 and the Environment (Air Quality and Soundscapes) (Wales) Act 2024 (the 2024 Act). Legislation empowers and obliges the Welsh Government and local authorities to act to reduce air pollution, including by declaring Air Quality Management Areas and smoke control areas , and introducing policies to bring pollution below legal thresholds. In 2026, the last Welsh Government used powers in the 2024 Act to set targets for reducing fine particulate matter pollution . The Welsh Government has also acted to reduce pollution from domestic burning, agriculture, and transport .

Concentrations of many major pollutants, including sulphur dioxide, nitrogen dioxide, and particulate matter, have fallen substantially in recent decades . Continuing challenges include urban ozone pollution and local variation in exposure. It can be challenging to isolate the specific impact of individual policy measures. Case studies focussing on Port Talbot steelworks closure and 50 mph speed limits on trunk roads illustrate how local air quality can change in response to industrial and transport developments. Action to reduce greenhouse gas emissions can also have a co-benefit of reducing air pollution, and therefore improving human and environmental health.

Research briefing by Charlotte Morgan and Dr Matthew Sutton , Senedd Research, Welsh Parliament

Senedd Research acknowledges the parliamentary fellowship provided to Charlotte Morgan by the Engineering and Physical Sciences Research Council (EPSRC) which enabled this briefing to be completed.', 'https://research.senedd.wales/research-articles/air-quality-and-public-health/', NULL, '', '', '', '', '', 'Senedd Research', '', '', '', NULL, 20.0, 'Noise', 'archive', 'local_government_enforcement', 'Housing system', '', '', 'environmental health', 0, '2026-08-04T14:04:46.483932', 'https://research.senedd.wales/research-articles/', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c4a38137855c57984cc', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'On that question of the errors, I know that Mr Fox raised this in the committee as well, and he was quite right to do so. It isn''t a good story to tell. There have been errors made in the past, but we should also say that some of the differences relate to individual interpretation. But there were also straight errors. So, all I can say is that I and the team will be looking very, very carefully at things from now on to make sure that things like that don''t happen again. You and Mr Fox are quite right to raise this point. It isn''t good enough, and I don''t think that anyone is going to sit here and say, ''It''s all okay.'' It''s not. There have been errors made in the past. We have to deal with those now and we have to ensure that that doesn''t happen in the future, because, at the end of the day, it affects the reputation of this place as a bilingual Parliament that is boasted about in Canada and a lot of other places, but failing to get consistency isn''t good enough. So, it is an issue that we''re looking at. Each week, going forwards, now, we will be looking at that and making sure, as best we can, that it doesn''t happen to that extent ever again.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4870&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.966977', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770617', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c66de8bf250aae9d5cb', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'A year-round tourism economy is something that I definitely want to see, both for the constituency that we both represent, but also for Wales generally. I think we''ve seen significant progress on that over the last few years, but there is more to do still on that. We have our investment priorities, and looking at how we can attract tourists for an extended period of the year is part of the criteria in how we invest in that. Also, we need to make sure that the business rates system that we have, and other taxation aspects, are also ensuring that those businesses that support the hospitality sector are able to be all year round. There''s no point having businesses that are only open for a particular part of the year. We need businesses that are open all year long, so that they can provide the opportunity for tourists to benefit, but also, what benefits tourists also benefits the communities they serve. So, I''m particularly hopeful that the positive sign that the Government was able to give yesterday for such a wide array of businesses that do support the tourism sector, of a 30 per cent reduction in business rates from next April, is a positive sign for the tourism sector generally that this Government backs it.', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Elin Jones', '', '162', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=3662&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'business rates', 0, '2026-09-19T12:39:17.011283', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769553', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6c9b434855a4f7fc63f8', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'I want to start by celebrating the huge contribution that tourism makes to Wales and my constituency in Ceredigion Penfro. Ceredigion Penfro is one of the most beautiful places in the world, shown by the millions who visit each year. In Ceredigion Penfro, you can travel from sandy beach to rolling hill to ancient woodland—and sometimes find all three in one place. From the only coastal national park in the UK in Pembrokeshire, to the remote wilderness of Ceredigion''s Cambrian mountains. From Tenby to Trefdraeth and from Aberaeron to Arberth, it''s no wonder that people across Wales and around the world want to visit Ceredigion Penfro.

 Tourism accounts for around 13 per cent of all employment in Ceredigion and 23 per cent in Pembrokeshire, so I''m delighted that this Government recognises the importance of the tourism industry to Wales. But evidence gathered from the previous Government showed that high levels of tourism, if not managed, can have a negative impact on an area. High levels of second homes and short-term lets can impact on local housing markets and the sustainability of local communities, particularly in areas where properties are not occupied for much of the year.

 It''s important that we are promoting tourism that provides maximum benefit to our people, environment, language and culture, and I welcome the lots of ideas that have come up in this debate already. So, I fully support the Government taking steps to enable sustainable tourism that secures jobs and income into local economies and which benefits our communities, environment, language and culture. And I support measures that prevent harm. That''s why I support the visitor levy as a choice for local authorities to ensure that local communities reap the rewards of tourism. Funds raised through the visitor levy enable investment in the local environment, the Welsh language and culture, and local infrastructure, which also supports tourism.

 However, it''s also important for the Government to act quickly when good policy intentions are not delivering the intended change and, in the case of the 182-day threshold, may be in danger of taking us in the wrong direction. Since becoming a Member of the Senedd, I''ve met with many constituents who have told me about the challenges that the 182-day rule for holiday lets is creating. I''ve heard about the pressure that the policy is putting on many self-catering businesses and the toll it is taking on people running local businesses. I''ve heard how it is threatening the viability of some local businesses, as well as jobs and spend in the wider economy, and I''ve also seen examples where it''s not achieving the intended outcome for the local housing market.

 So, whilst I fully support the intention of the 182-day rule, I also welcome this Plaid Cymru Government''s commitment to keep the 182-day occupancy threshold under review, and I urge the Government to begin this work quickly, so that we can find pragmatic solutions that better support the original purpose of the policy. This should include whether 182 days is the right threshold, but also have clear and reasonable exemptions, particularly where a property would not qualify as a private home. We need clear guidance to avoid holiday let owners being left stunned by unaffordable backdated council bills, sometimes by three or four years, or living with the mental stress that they soon could be. So, that''s why I''m pleased to support the Government amendment today, and I urge other Members to do so. Diolch.', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Anna Nicholl', '', '12178', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=12193&l=en', NULL, 77.0, 'Medium', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', '', '', '182 days; holiday let; holiday lets; second homes; self-catering; short-term lets; visitor levy', 0, '2026-08-04T14:03:16.759645', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767061', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6cfd8297a52c17151ef4', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'So is there a capacity issue on the other side as well as drafting?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=830&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.181467', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770402', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('6d06b513c5d050f33f2a', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'So, obviously, where you can save time, you can focus your attention on other areas, can''t you?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Adrian Mason', '', '12181', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5125&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.014579', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770513', NULL, NULL, NULL, NULL);
