INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9cf5f739eb30f59f16b7', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Sorry, Chair, I have more questions on data.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Elyn Stephens', '', '12164', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2321&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.044348', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769867', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d2159718b1d62082ab2', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I''m sorry to interrupt you in full flow.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5247&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.050581', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770548', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d242ac49de82d581434', 'other', 'Statement of Opinion', 'Statement of Opinion - OPIN-2026-0528', 'This Senedd: 1. Notes the efforts of successive governments to tackle fuel poverty and improve household energy efficiency, ...', 'https://record.senedd.wales/StatementOfOpinion/528', '2026-06-16', 'Vikki Howells', '', '5107', '', 'Pontypridd Cynon Merthyr', 'Senedd (tabled business)', 'Tabled on 16/06/2026', '', '', NULL, 35.0, 'Low', 'dashboard', 'energy_efficiency', 'Property & energy', '', '', 'fuel poverty', 0, '2026-08-04T14:04:11.001818', 'record_search:type=other:query=energy efficiency', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d3a872af1c494a1f9a8', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Well, it''s something that we haven''t actually addressed firmly yet; we''ve thought a fair bit about it. There is nowadays, of course, a tendency to use secondary legislation frequently in every legislature. That''s just the way things are. As for the balance, well, secondary legislation is vital in order to get the nuts and bolts in place for things to work. And so we are mindful of the need, again, not to overload that particular sector so that it impinges upon your work. Having said that, it is a fact today that modern legislation means that there will be a considerable amount of statutory instruments and secondary legislation coming through, and that is something that one cannot prevent in a way; it''s a necessity. I don''t know if—.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1197&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.246517', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770357', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d6e5b8ca6784ae9be50', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''d be interested, if you wouldn''t mind keeping us up to date, in the conversations you''re having with those other Cabinet Secretaries. This area that we focus on, obviously other committees across the Senedd do as well, so it would be quite useful if you could keep the wider Senedd updated on that discussion as it goes on. I''ll bring Vikki and Andrew in, and then I''ll come to you. Thank you.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4733&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.918345', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771780', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9d79d21e05038b29e717', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'I think that will vary between local authorities. Council tax is the obvious one. We use housing tenants records, but, for some local authorities, that won''t be possible because they''re outsourced. So, there are going to be some difficulties. We used adult social care data, which was very good in Powys, because we''re a large rural area and take up quite a large portion of Wales. Employee data was very good, because quite a lot of our staff work within the county. That won''t be as useful for others in the small urban areas. Sometimes, I think they''re going to need to start those discussions and find out what—. I''m not sure if I can recommend, because I don''t know the quality of some data sets in other local authorities. But looking at the standard that came across from the pilots, we all used two or three core sets, as I said, like council tax, education records, and it''s then looking at what else might be strong within your council, because the EROs have to have faith that the data that they receive is of good enough quality.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Sandra Matthews', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=6863&l=en', NULL, 109.2, 'High', 'digest', 'taxation_of_property; committee_scrutiny', 'Housing system; Tax & finance', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; council tax; evidence session', 0, '2026-09-18T11:33:49.677730', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769963', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9dade9bd53e3592531fa', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you. I can take this question. I think one of the things that I think the Welsh Government have flagged in their correspondence with the committee and in their explanatory memorandum for the regulations is, firstly, about the benefit of reducing that minimum time period—sorry, the minimum frequency—for this first year of implementation, which is aimed, they''ve said—and we agree; this is important—at reducing some of the administrative challenges in this first year for EROs.

 I think it''s also worth—. It''s helpful to note that the regulations set the minimum floor, if you''d call it that, for activity, that all EROs will deliver each year. So, there could be more flexibility for EROs to carry out more than one data matching exercise in future years if they wanted to and if they felt that that was going to be important to deal with the particular circumstances. And there''s a range of factors that we think they will be taking into account when they consider whether one exercise or more than one exercise is necessary and useful. So, that might include whether they''ve got scheduled elections in that year and what types of elections those are, whether they have got significant issues with some of those other electoral administration contact points and processes, such as the annual canvass, and, as the committee has already pointed out, whether there are particular local demographic circumstances where we''ve identified significant under-registered groups, including student populations, and then particularly thinking about the timing of when that activity would happen in relation to those under-registered groups. So, there is still flexibility within that year to, (a), change the time of when the exercise would take place and, (b), for electoral registration officers to decide it would be helpful in a particular year to carry out more than one exercise. 

 I think there''s just a couple of other things to point out. One is that, in terms of the impact on accuracy and completeness of having one exercise rather than four, the automatic voter registration process is a complement not a replacement for the other registration processes that will continue. So, both the annual canvass that''s happening at the moment will continue to happen, and also the ability for electors to register immediately before a particular set of polls, using the online registration portal. So, automatic voter registration is there to supplement that, rather than to replace those.

 And, I think, even looking at whether we''re looking at one exercise or more than one exercise, even based on the findings from our evaluation, I think we''d flag that, even if there was only one exercise per year, it would still potentially be leading to an improvement in the completeness of the registers of somewhere between 2 per cent and 8 per cent, based on the experience from the pilot. So, that''s still an important and helpful improvement on the accuracy, compared with where we are at the moment.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1637&l=en', NULL, 109.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', '', 'Legislative commitment; Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; explanatory memorandum', 0, '2026-09-18T11:33:48.940193', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769837', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e011a2506749f715bf5', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'The Welsh Government will be held to account by the regulator in the same way as the bodies that are in Wales are held to account by the EHRC. It is not for the Welsh Government to issue that guidance.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=3357&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.933434', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771193', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e2f79e27ff0b0ead2d6', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch yn fawr. Thank you.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=7704&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.390107', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771764', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e43921e03efbe3ae332', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Just to follow up, would you be able to provide a bit more detail on the discussions you''re having with your UK counterparts around this as well? Are they constructive conversations? Because, obviously, like you said, it''s a really big challenge, and the UK Government have a big role to play in that as well as us. I was just wondering how that dynamic is working in those conversations.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4409&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.867178', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771855', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e601c965f9e44f9b5a7', 'plenary_transcript', 'Plenary', '7. Reform UK Debate: The tourism sector', 'Can you confirm that you understand that the money raised from the visitor levy is ring-fenced for visitor purposes, not to pay debt or anything else?', 'https://record.senedd.wales/Plenary/16084', '2026-07-08', 'Huw Thomas', '', '12156', '', '', 'Plenary', '7. Reform UK Debate: The tourism sector', '16084', 'http://www.senedd.tv/en/16084?startPos=13207&l=en', NULL, 38.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'visitor levy', 0, '2026-08-04T14:03:16.895860', 'https://record.senedd.wales/XMLExport/Download?meetingID=16084&xmlDownloadType=EnglishTranscript#767093', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e60a7e0fb9c9c8c1db0', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'You said you''re meeting the planning Minister next week. In the UK, the UK Government some years ago changed the planning system in England to have a presumption on permitted development rights for redundant buildings to be converted into housing, or office space, as such, to create economic activity and to meet some of that pent-up housing demand in rural areas. Are you supportive of such a change here in Wales? I appreciate it''s not your portfolio—', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Andrew R.T. Davies', '', '143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4842&l=en', NULL, 63.2, 'Medium', 'digest', 'planning_system; committee_scrutiny', 'Housing system; Planning & place', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; permitted development; planning system', 0, '2026-09-25T06:30:34.936747', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771790', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9e8157f17470c22e5d0b', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Yes, certainly. Obviously, as we''ve discussed in this committee in the past, there are differences in terms of powers. We know, for example, that one of the most powerful levers that would be able to lift families out of poverty is the welfare system. We know that the welfare system as it currently stands isn''t fit for purpose, but we don''t have those powers. But, we do think that, within the powers that we currently have, there are things that we can do. So, there are levers that are within our powers. We are certainly going to look at the international picture to see what works. Cynnal is a perfect example, where, of course, we''ve seen how that has made a difference in Scotland. We don''t have the power to roll that out in the same way as has been done in Scotland, but we hope that, through the pilot that we''ll be holding and then by ensuring that we evaluate the impact that that has made, that that will be able to show the way forward for us in terms of how we can tackle poverty and how the targets could reflect the kinds of actions that we can take. But, certainly, officials are engaging with other nations and regions.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=672&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.625714', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771173', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eb2981cecb717f2e885', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'We''ll be done in time—', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6799&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.276856', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771252', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9eb65a41852c9b97dc97', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I think there''s always a balancing act in terms of developing a legislative programme, and what you''ve got here is a series of pieces of legislation. Some of those pieces of legislation have been a topic of some work already, and there have been discussions in the previous Senedd on some of these topics. There''s also a recognition that—and this maybe comes on, in part, to our approach to legislating in certain areas—more focused, shorter Bills are of of clear benefit, and would allow prompt action in areas. So, for example, you will be familiar with the Plaid Cymru manifesto on a range of areas around housing and planning. There may well be the case that there would be further housing legislation during the four-year time, but we begin with a short, focused Bill around renting. So, that''s the approach we''re trying to take.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=395&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Legislation Committee; legislative programme', 0, '2026-09-22T11:55:09.106257', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770370', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9ecca57a48c20265b84c', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Marc, you''ve got a question.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Carmelo Colasanto', '', '12152', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1287&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.880445', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769865', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9f7c04e557db2963bc21', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much. This was one of the areas of work within my portfolio that we started work on very swiftly within the first 100 days. You''ll know, of course, that it''s a statutory requirement for a new Government to review the strategy after being elected, and we decided that this was going to be one of the first things that we would do. You''ll perhaps remember that I was chair of the cross-party group in the previous Senedd on violence against women and children, so this is something that I felt very passionately about and I knew that we needed to look at the gaps that continue to exist in terms of the strategy.

 So, we undertook a very swift statutory review within the first 100 days. That review included survivors, people who provide expert services, partners, of course, who deliver elements of the strategy on our behalf, and, of course, the national adviser, Jo Robinson. So, the findings of that review will now feed into the new national strategy.

 So, on Monday, as it happens, I discussed this in the Cabinet. I presented a paper to the Cabinet about the strategy and what the timescale will be in terms of the new strategy, and I emphasised there the importance of this being seen and understood across every portfolio in order to bring VAWDASV to an end. So, they share the ambition, the entire Government shares the ambition, that this has to be a whole-system and cross-governmental approach. And I have had two very positive and beneficial meetings since entering this role with the national adviser, Jo Robinson, and we have been discussing what needs to be done.

 So, in terms of what we''ve already seen being done—and as I said, we''re still consulting on this and thinking about how this will take shape in the next strategy—I think that one of the gaps that we need to consider in terms of the new strategy is online harm. This is something that is becoming increasingly prominent and is something that, perhaps—. It''s not new, but it is something that continues to develop with artificial intelligence and so on. [ Inaudible .] Yes.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=5117&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.086438', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771321', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9fbfa5c442ee68ec2b07', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Great, thank you. I think I''ll start with that question. I think the first thing that we wanted to say was, really, that these regulations are a really important and welcome first step forward in terms of modernising electoral registration and helping to improve both the accuracy and completeness of electoral registers, which is something that our research has been highlighting as a concern for many years, both in Wales but also across the UK as a whole.

 Just in terms of the issues that our evaluation highlighted and the recommendations that we made to Welsh Government and to electoral registration officers, many of those have already been addressed in these regulations, which, again, is very welcome, for example the change to the minimum frequency of the AVR process, the shorter notification period and, particularly, the requirement for the notification to be sent in hard copy by post and also to be accompanied by the invitation to register for the UK parliamentary register. So, some important and welcome changes to the process as a result of the evaluation. But we do think, flowing on from the experience of the pilots last year, there are some outstanding challenges around implementation, and we''ve highlighted those in our written evidence and are aware that other organisations have also highlighted these points.

 So, there are three particular points that we think are worth bearing in mind. I think, first, it''s clear that we have some increasingly challenging timescales in terms of when the regulations will come into force, and then the subsequent activity that registration officers will need to make sure takes place so that electors can get registered and added to the register automatically in time for the local government elections next May. And those timescales are going to be placing a lot of pressure on electoral services teams at a time when they are already delivering the annual canvass this year and when they should be beginning their preparations for the elections next year. The second area that I think we want to highlight is around the electoral management software systems that registration officers use and the functionality that''s going to be needed—the new functionality that''s going to be needed to deliver automatic registration. We still have some uncertainty about when those updates to those systems will be available and ready to support the delivery of automatic registration. And then the final point is possibly a longer term point as well, which is how best to ensure greater consistency across Wales in terms of the data sources that the ROs are able to access for the purpose of identifying new electors.

 So, I think, for this year, these kinds of challenges will undoubtedly make it harder to deliver automatic voter registration. But as I said, this is an important first step in the right direction and it also provides a process that can continue to be refined and improved over the next few years, as we build towards the next set of Welsh elections in 2030 and 2032.

 And we also just would like to, I suppose, highlight that it would certainly be something of a missed opportunity if we couldn''t get to a point where AVR could be rolled out ahead of next year''s local elections, because it would mean that voters would not see the benefit in real terms in being able to participate in elections until the next Senedd elections in 2030 at the very earliest.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=189&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; written evidence', 0, '2026-09-18T11:33:48.707822', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769809', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('9ff913f4c22ca738aabb', 'legislation', 'Welsh Statutory Instruments 2025', 'The Council Tax (Alteration of Lists and Appeals) (Amendment) (Wales) Regulations 2025', 'The Council Tax (Alteration of Lists and Appeals) (Amendment) (Wales) Regulations 2025', 'https://www.legislation.gov.uk/wsi/2025/1323/made/data.xml', '2026-02-02', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 45.5, 'Low', 'dashboard', 'taxation_of_property', 'Tax & finance', '', '', 'council tax', 0, '2026-08-04T14:04:15.218802', 'https://www.legislation.gov.uk/wsi/2025/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a00b3b411c0c8cf7e186', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Finance', 'Diolch. Cabinet Minister, councils across Wales are at breaking point. Council tax rises this year have already added around £104 on average to band D bills across Powys, Neath Port Talbot and indeed Swansea, yet people are still paying more whilst roads crumble and front-line services disappear too. And now we are losing our primary schools. Cradoc primary school, for instance, in a nearby village to me, has already closed. When a primary school is closed, it''s ripping out the heart of our communities. And clearly, under this Plaid Government, more school closures are coming too. My main question is this: as you have now commissioned a review of the funding formula, including rurality and sparsity, will you now admit that the current system is failing, and will you guarantee fairer funding, so taxpayers aren''t continually asked to pay more for less, while our communities lose their services and more children lose their primary schools too? Diolch.', 'https://record.senedd.wales/Plenary/16261', '2026-09-16', 'Iain McIntosh', '', '12170', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Finance', '16261', 'http://www.senedd.tv/en/16261?startPos=5673&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'council tax', 0, '2026-09-19T12:39:17.244593', 'https://record.senedd.wales/XMLExport/Download?meetingID=16261&xmlDownloadType=EnglishTranscript#769646', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a0cc35118f63cb1108e5', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Thank you.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Rebeca Phillips', '', '12172', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2817&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.121712', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769929', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a0f737ac2df11bf1bb98', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. That''s really good to hear. Another part as well that I wanted to come in on, and it''s something I''m quite interested in, is to do with the nature finance side as well when it comes to biodiversity. I was wondering if the Welsh Government has looked at that aspect of things, because I think there''s possibly quite a lot of potential there in getting public and private investment in when it comes to helping with biodiversity and restoring our natural ecosystem. So, is that a piece of work you''re looking at doing?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3013&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.735507', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771898', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a10fad88d1d0001cfea6', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Welsh Labour''s red lines on the supplementary budget have been clear from the outset: a substantial contribution for additional learning needs in our schools, utilising some—not all, some—of the consequential made available by the UK Government spend in this area in England. Plaid Cymru''s initial proposals contained not one penny for ALN. This fact is made very clear by the concerns raised in the Finance Committee report. A petition on this issue attracted 11,000 signatures in two weeks. And in the end, seven days ago, Plaid finally put some money on the table.

 We are clear this is not enough, but this is not our view alone. As has been said before, Welsh councils are united on how the pressures from ALN in schools are real and urgent. Many of us will have received correspondence from school leaders, outlining the immediate difference extra real funding could make, and we are all aware of the concerns felt by teaching unions. Extraordinarily, overnight, the two teaching unions that represent school leaders, the NAHT and ASCL, have written jointly to Welsh Government to state that they are now in formal dispute with the Government over the issue of pay and ALN funding. These aren''t militant unions. They''re not affiliated with the Labour Party. In fact, one of them used to be led by the education Minister.

 So, how has it come to this, just 64 days into a new Plaid Cymru Government, where two large, well-respected unions are having to ask for the intervention of an independent conciliation body to mediate its dealing with Welsh Government? It''s unprecedented. It''s a failure of social partnership, and it says very clearly that the supplementary budget, as proposed, isn''t good enough. Not our assessment; the blunt assessment of teachers, school leaders and their representatives.

 I heard the Trefnydd''s response to Lynne Neagle earlier in the business statement. It sounded to me very much like the response of a Government that''s stopped listening. Let me spell it out. Forty million pounds in one year is a bad deal. Forty million pounds in the second year, when it''s been eroded by inflation and demand growth, is a bad deal. Forty million pounds in the third year, when £200 million of further recurring consequential become available from ALN spend in England, is a ridiculous deal. No financially literate party could sign up to it.

 Llywydd, this Senedd Labour group is returning to our party''s foundational mission, being the political representation of organised labour in the nation and being the voice of the most vulnerable in our society. You will understand, therefore, given the fundamental and formal concerns that unions have regarding these proposals, how we simply cannot support the supplementary budget as it currently stands. There are some on the Plaid benches that are avowed socialists. Here is an early test for you: will you blindly follow your party''s whip, or will you vote with our pupils and our teachers?

 And let''s also be clear, Llywydd—[ Interruption .] Let''s also be clear—', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Thomas', '', '12156', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24002&l=en', NULL, 71.5, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; supplementary budget', 0, '2026-08-04T14:03:10.584289', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767877', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a127dbeb5568b49c9fa3', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''m sure she was.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6327&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.154209', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772123', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a19c6567e62eadebe038', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'But, Chair, if I may, if there are particular examples when either the LCM is deficient in some way, or whether an explanatory memorandum hasn''t reached a suitable level of detail and standard—. I would assume that officials would already be in touch with colleagues, but if they are not, please ensure that that happens, because that serves none of our interests.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3932&l=en', NULL, 115.0, 'High', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', 'Legislative commitment', 'LCM; Legislation Committee; explanatory memorandum', 0, '2026-09-22T11:55:09.766534', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770442', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a1ef9dff70304937e6ad', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'No, I was looking for it.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', '', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23409&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.522792', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767983', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a23f0ca321bccf2aecbc', 'calendar', 'Senedd forward look', 'Legislation Committee — 05 October 2026, 13.30', 'Legislation Committee is scheduled to meet on 05 October 2026 at 13.30.
Meeting status: Confirmed
This is an opportunity to influence: committee papers and any call for written evidence are normally published in the two weeks beforehand.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=986&MId=16302', '2026-10-05', '', '', '', '', '', 'Legislation Committee', '', '16302', '', '2026-10-05', 48.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Legislation Committee; written evidence', 0, '2026-08-11T07:47:52.289917', 'https://business.senedd.wales/mgWebService.asmx#GetAllMeetingsByDate', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a2cdbdcbedad680c8356', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes, I think it''s fair to say that the experience from the pilots in particular last year shows that the data matching processes that were used were effective; they worked. So, they supported the process and they did result, ultimately, in voters being added to the register. But it''s also really important to recognise that, as our evaluation pointed out, this was time consuming and quite labour intensive for registration officers in the pilot areas.

 So, yes, there is definitely learning and improvements that could be made. Part of that is about ensuring that the specification for the electoral management software systems is really clear and it meets the needs of registration officers. That specification is being finalised now; it hasn''t yet been confirmed and released, so there is still a little bit of uncertainty about what that process will involve. I think, again, it''s fair to say that, if it had been clear earlier in the development process for this year, then that would have relieved some of the concerns that electoral services teams probably are feeling about the process at the moment.

 The other thing that Welsh Government are very helpfully doing at the moment is providing EROs with data impact assessments and template data sharing agreements that they can use to help get in data from the local data holding departments. That should also be really helpful in getting some consistency.

 Registration officers already do have some experience of running data matching exercises every year. They''re running a national data match exercise using UK Government data ahead of the canvas, and they''re also able to supplement that with local data matching as well. So, they do have experience of these processes in general terms; what they don''t have necessarily is the experience of exactly what this system will provide and will require. So, yes, I think this year, the first year, is going to be more challenging and, in future years, there will be opportunities to refine and improve that process, absolutely.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=2174&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.023876', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769849', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a31a43fc21dcac952b40', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'If it''s any help, I can pass details over.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'John Davies', '', '4650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3193&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.768908', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771917', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a33bfdd70b93188c1ea5', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'That''s exactly why I''m asking the question. One of my critiques of this place, generally, has been that they''ve passed some very well-meaning legislation, but have not been able to put the resources behind it to effect the changes that they were looking to see, and I think that''s one area that we need to continue to scrutinise.

 My last question, and this picks up on the rural-proofing Bill, which, as I read it, at early days, seems to be a catch-all for quite a lot of different things that Welsh Government officials have been wanting to do for some time, and then the statutory duty around ensuring that rural needs are considered. Candidly, I''m also concerned about urban needs, and when I look at certain protected characteristics, I would probably argue that there are a higher proportion of people who have those characteristics living in urban areas as opposed to rural areas. So, I guess my question is: how can we avoid the danger that this legislation creates a two-tier system, where certain parts of Wales are given stronger rights than others?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Huw Thomas', '', '12156', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=2248&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.457725', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770440', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a37e7e72712926fc9807', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'My final question is about supported housing. Are you getting data on supported housing so you can contact the people who may be in the Wallich for three months and then move on to another organisation for six months, and then move into a HMO?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Mike Hedges', '', '332', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5338&l=en', NULL, 138.0, 'Critical', 'immediate', 'hmos_and_standards; committee_scrutiny', 'Housing system; Private rented sector', 'Opposition housing leads', 'Opportunity to influence', 'HMO; Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.402366', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769968', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a37f3018562087f8a83b', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Just a couple more points. Policy development is absolutely fundamental, obviously, and the processes around that. Are you having to improve, or are you reviewing how the policy development processes are working so that you can get a stronger handle on that?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peter Fox', '', '4787', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3082&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.613391', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770478', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a3a63ab3c2993396d9df', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you. One area that I could say that definitely needs updating is the way that the Welsh Government''s energy policy is in planning policy, especially regarding ''Future Wales: the national plan 2040''. We all know that is outdated in regard to industrial-scale wind turbines and pylons across a vast part of rural mid and west Wales. We all know about the 220m turbines that are going to be erected if Bute Energy have their way. That would absolutely decimate my communities. But, in ''Future Wales'', it doesn''t actually take into consideration the current size of those turbines that are currently being proposed. It also doesn''t take into consideration the low-frequency noise that they generate as well. So, I''m asking you, Minister: are you willing to put a moratorium on these large-scale industrial plans for rural mid and west Wales, because unless planning policy is updated, we are going to see something potentially approved that will have devastating long-term impacts on communities without having updated planning guidance to make an informed decision?', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'James Evans', '', '8585', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4863&l=en', NULL, 71.5, 'Medium', 'digest', 'planning_system', 'Planning & place', 'Housing minister; Other committee chairs', '', 'Future Wales; planning guidance; planning policy', 0, '2026-08-04T14:03:05.162095', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768151', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4194c85ec3a6487c091', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Not yet, no.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Catherine Hunt', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=3677&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.145926', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769908', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4528adab5382dfc5512', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'Thank you for the contribution.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Elin Jones', '', '162', '', '', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', '16260', 'http://www.senedd.tv/en/16260?startPos=10797&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:26.196904', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769228', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a46da4e63cc7b4019480', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Adrian, did you want to come in?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=1825&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.351632', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770386', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4baa4d45cb7da187ada', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I assumed Niamh was directing the question at me.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Richard Irvine', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6326&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.152622', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772122', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a4edb171563b5ae923a2', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much for that question and for an opportunity to explain some of what was contained within the written statement issued on Monday. You''re exactly right, we want that target of 20,000 to include vacant properties above shops on our high streets, and this will be part of the work of the town centre taskforce, of course, and how we accelerate the process to allow more vacant properties to come into our housing stock.

 I do emphasise that I think it''s important to be entirely transparent and, therefore, I have said that only homes that will remain as social homes for communities and families will be counted as part of that 20,000 target. Now, what exactly the percentage will be between new builds and acquisitions in terms of vacant properties and so on, I can''t give you an exact figure on that. But, also in that statement made on Monday, I have spoken of community-led housing and I would like to include housing that''s created through community groups—through the community right to buy, for example—and that we also include those within the target because they do provide a solution that is in keeping with those communities in rural areas and where the Welsh language prospers.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4546&l=en', NULL, 77.0, 'Medium', 'digest', 'housing_supply; social_housing', 'Housing system; Planning & place', 'Housing minister', '', 'community right to buy; right to buy; social homes', 0, '2026-08-04T14:03:05.129226', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768122', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a52ae88087a156b61429', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'How confident are you that there''s no duplication? Because, obviously, when a person''s registered, say, in Powys, and they go off to university in Pontypridd, they register there and they register in Powys. How can you tell if they register in two places so that they''re able to vote in two places?', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=5419&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.421720', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769998', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a55b476abd7a458a2e52', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes. Good morning. Thank you, Chair. I am Tom Hawthorn. I am head of policy for the UK Electoral Commission.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=127&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.690640', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769801', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a59d80dff5d28da2aeb3', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Andrew Charles, deputy director of the cohesive communities division.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Andrew Charles', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=93&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.562421', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771143', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5c74391fe628d4a12a2', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'Thank you for the question from the Member. As the Member said, in the supplementary budget yesterday, as far as health is concerned, we had a focus on outcomes, on improving people''s health and well-being by introducing more funding into tackling the waiting lists, and it was extremely disappointing, to say the least, to see people who have said that they wanted to support such a policy vote against it. We want to improve people''s outcomes and make sure that the impact on patients is better. So, we have made sure that NHS Wales Performance and Improvement are now involved. They have agreed an intervention approach in the Aneurin Bevan University Health Board to support them. Their improvement plan focuses on supporting frail and older people in the community—exactly answering the points that the Member raised—increasing the front-door capacity for people with complex needs and ensuring timely discharge. We have also allocated an additional £3 million this year to enable the delivery of the improvement plan.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16086', 'http://www.senedd.tv/en/16086?startPos=194&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:04.684752', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768029', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5e0ef61dc818316eafe', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Diolch. I''m sure we''ll want to keep up to date on that as well. Diolch, Gadeirydd.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jayne Bryant', '', '5038', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=6544&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.238950', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771310', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5e0f6c8e2a2821ac2c5', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'As someone who was a county councillor until recently, I can attest to how important it is to pass this supplementary budget today in order to address the challenges facing local government. Labour has made much over the last few weeks of the need to see urgent investment in ALN services, and everyone recognises that. It is therefore strange to hear today that they intend to vote against the budget, despite the fact that there is more money for ALN services in this budget than they themselves had originally called for. I''m sure that the families, teachers and pupils, who are calling for the same investment, will find that strange and frustrating too.

 Beyond the funding for ALN services, the supplementary budget also ensures additional investment for expanding free school meals and improving the condition of our schools. I am sure that everyone across the Chamber shares the same desire to see pupils with full stomachs learning in schools that are fit for purpose. But, by voting against the budget today, we are preventing that investment from reaching our schools as soon as possible, and it is the pupils and teachers who will miss out.

 Llywydd, it is not just the additional direct funding that is essential for the sustainability of our local authorities. The additional investment of £145 million in the health service takes pressure off care services. The £55 million for childcare creates local jobs and helps parents back into work in order to strengthen our local economy. And the £8 million for the bus travel scheme for young people improves connectivity and enables our young people to socialise and make use of local resources.

 In conclusion, Llywydd, the vote before us tonight asks a relatively simple question, really: do we want to see a sustainable health service? Do we want to give every child across Wales the best start? And do we want to support all pupils to realise their potential and all teachers to enjoy their work? We can only do that by passing the budget before us, and I encourage all Members to support it. Thank you.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elfed Williams', '', '12165', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24654&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.658942', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767904', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a5ff7c4f0e93c5749051', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I think ''acknowledged'' is probably the best term. Let''s see how far we can progress those discussions now. But an acknowledgement is the beginning of a conversation, at least.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4160&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.821244', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770473', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a60cd69d5764819eed88', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Diolch, Lywydd. I''m pleased to speak in this debate today on behalf of the Finance Committee. We had the privilege of scrutinising the first supplementary budget on 9 July and our report makes 22 recommendations. Today, I will focus on some of our key recommendations. 

 As we''ve heard, the supplementary budget that the committee scrutinised included £246 million of unallocated resource funding, which the Cabinet Minister said reflects substantial in-year pressures, particularly within the NHS. We recognise that there is always some uncertainty at this stage of the financial year and that Governments need a degree of flexibility to respond to emerging pressures, but the level of unallocated funding is considerably higher than in recent supplementary budgets. The committee noted that the average over the last four years has been £62 million and it''s currently around four times higher than the average of the last four years. We want to better understand what pressures remain across Government and how those pressures differ from the normal challenges of managing a budget through the financial year.

 Turning to the management of NHS finances, this supplementary budget includes a £100 million allocation to tackle NHS waiting lists. The committee supports the Government''s ambition to move beyond short-term interventions and deliver sustained improvement in NHS performance. And we heard the Cabinet Minister wants to focus on longer term outcomes rather than short-term monthly performance measures. We heard that the NHS is currently facing financial pressures of more than £300 million this year and that discussions with health boards are ongoing before further funding decisions are taken. However, what we did not hear in sufficient detail is how the approach of this Government differs from previous approaches that have also relied on significant in-year NHS allocation. That is why we asked the Cabinet Minister to detail the accountability mechanisms and measures in place to ensure the £100 million for reductions in waiting lists is used effectively, and to explain the practical differences between the previous approaches to NHS funding and the new Government''s approach. We want to understand how these investments will drive sustainable improvement rather than short-term recovery measures.

 Moving on to the allocation of funding arising from the one-off special educational needs and disabilities consequential. Firstly, we recognise that the principle that Barnett consequentials do not have to be spent in the same way as funding allocated in England is an important principle. We also recognise the very real pressures facing additional learning needs services across Wales in the here and now. The Cabinet Minister told us that this one-off consequential has been absorbed into wider budget management. That inevitably raises questions about sustainability in other areas. We therefore ask her to explain how allocations enabled by this one-off consequential will be managed in future years, when that funding is no longer available. The Cabinet Minister told us the Government wants to work with local government and develop a more sustainable model for additional learning needs provision, recognising the significant pressure in the system. That is why we''re seeking greater clarity on both the scale of the challenge and the Government''s plan to manage these pressures.

 The committee noted the Government''s plans to expand funded childcare. The supplementary budget includes £55 million to accelerate the roll-out of funded childcare for two-year-olds and to support the wider expansion of the childcare offer. We asked the Cabinet Minister to confirm how many places the £55 million allocation will support, what outcomes are expected from the funding and how those outcomes will be monitored and reported.

 We will now turn to capital budgets. The Government has chosen to allocate virtually all available capital funding at this stage of the year. We understand the rationale and recognise the benefits of allocating capital funding early to facilitate delivery and support economic activity, however, that approach also leaves limited flexibility should circumstances change. We''re particularly concerned by reports that UK Government decisions associated with defence investment could have implications for Welsh capital budgets. We asked the Cabinet Minister to provide an assessment of the implications of the UK Government''s defence investment plan and any consequences for Welsh Government capital budgets.

 Too often, debate focuses solely on the amounts of money being spent; the Finance Committee understands that what matters most is what that money delivers. We look forward to the Cabinet Minister''s response and to continue our scrutiny of these issues as the financial year progresses. Diolch, Lywydd.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Sam Rowlands', '', '8734', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=23424&l=en', NULL, 60.5, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'Other committee chairs', '', 'Finance Committee; supplementary budget', 0, '2026-08-04T14:03:10.526566', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767956', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a61543814a7dd6a7e46a', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'Yes, I agree on that as a risk. So, our evaluation noted that one of the sort of drawbacks, I suppose, of the shorter notification period would be, (1), adding an elector to the register when they don''t want to be added. So, this is obviously the concern you''re talking about, and the principle behind it is less time to receive the letter and have sight of it and then contact the ERO. And then, a kind of secondary risk, I suppose, of adding an elector to the register incorrectly, where perhaps the letter goes to a house where the intended recipient no longer lives, or never lived, so, again, it''s less time for existing residents to be able to contact the ERO. In terms of potential mitigations to this, and just trying to find that right balance between deliverability and meeting some of those concerns, there''s the fact that the open version of the register for devolved elections in Wales will have been abolished. That''s the change that the Welsh Government will be bringing in from October, as part of the preparation and the groundwork for these regulations. That''s something we''ve welcomed and previously recommended, and it will mean that, for people who are added to the register via any process now for the devolved version in Wales, businesses et cetera won''t be able to purchase a copy of that open register.

 And then, going back to some of our recommendations, a lot of the recommendations in our evaluation were focused around this issue. So, for example, we recommended that the notification letter should have to be sent in hard copy rather than by e-mail, for various reasons, but one of which was that a hard copy notification is more likely to be noticed, less likely to be missed. Also, the regulations themselves have a few prescribed things that the notification must say. So, it must have information on the ability to opt out. It must be have information on the ability to apply for anonymous registration, if applicable. And it also has to specify the final date of the day of the notice. So, that''s all a kind of good level of mitigation from our perspective. 

 And then, in terms of engagement with groups—I think we mentioned this in our written evidence—we understand the Welsh Government is considering or planning some form of engagement with relevant stakeholders on anonymous registration and communicating the changes. From an Electoral Commission perspective, we''ll be updating information on our websites around registration, if the regulations are passed, to reflect automatic registration as a kind of new system in Wales. And, as part of that, we''ll include information highlighting that there options to opt out of the process, options around anonymous registration. 

 I think the only other thing I''d just add, if that''s okay, is, from the feedback of the authorities running pilots—and, obviously, we''ll want to look at this again as part of a national roll-out, and satisfy ourselves that it''s a similar kind of picture—across the pilots, where potential electors did contact the ERO wanting to opt out, it was a very, very small number. So, it was between 0.2 per cent, I think, in Newport—. It was 0.2 per cent in Gwynedd, sorry, and 4 per cent in Newport, and then Powys somewhere in between. So, really relatively small numbers, and I think a very common reason—possibly the most common reason—was parents checking if it was correct that 14 and 15-year-olds should be added to the register as an attainer. So, in that case, following an explanation from the electoral services team, that that is in fact the case and that it would be the same process for an attainer if they registered as an attainer in the normal manner, that query was resolved. Others chose to opt out. But, yes, a small number of queries from people as well who didn''t want to appear on the register for safety reasons, and they were concerned by the notification that they were about to be registered. So, in that situation, electoral services teams can, obviously, highlight the option of anonymous registration, but, from the experience of the pilots, a lot of people weren''t satisfied by the process or the option of anonymous registration either and would prefer to avoid registering entirely.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Davies', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=937&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session; written evidence', 0, '2026-09-18T11:33:48.828907', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769805', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a74c0c63ede1e9b83876', 'press_release', 'Welsh Government — Announcement', 'Welsh Finance Minister to press UK Government for fairer funding at Cardiff summit', 'Welsh Finance Minister to press UK Government for fairer funding at Cardiff summit
Welsh Government to host finance ministers from across the UK in Cardiff Cabinet Minister for Finance Elin Jones to press UK Government on fiscal reform, including a formal review of the 2016 Wales Fiscal Framework. Finance Minister: "The way our funding is calculated hasn''t kept up with the real needs of people here. It''s outdated, and it''s not transparent enough. That must change."

Welsh Government to host finance ministers from across the UK in Cardiff Cabinet Minister for Finance Elin Jones to press UK Government on fiscal reform, including a formal review of the 2016 Wales Fiscal Framework. Finance Minister: "The way our funding is calculated hasn''t kept up with the real needs of people here. It''s outdated, and it''s not transparent enough. That must change."

Wales will host finance ministers from across the UK in Cardiff today (Thursday 17 September) when the Cabinet Minister for Finance will make the case for a funding deal from Westminster that reflects what people in Wales really need.
The meeting, known as the Finance Inter-ministerial Standing Committee (FISC), brings together finance ministers from the UK Government, Wales, Scotland and Northern Ireland to discuss financial and economic issues faced in all corners of the United Kingdom.
A one-to-one meeting between the Finance Minister and the Chief Secretary to the Treasury will also be held as an opportunity to discuss issues specific to Wales.
The Cabinet Minister for Finance will raise several priorities for Wales to deliver fiscal reform, including:
A formal review of the 2016 Wales Fiscal Framework – the agreement that sets out the Welsh Government''s funding arrangements including its tax powers and fiscal management tools such as borrowing - to make sure Wales'' funding arrangements are fit for the future.
Stronger borrowing powers and more flexibility over reserves, so Wales can plan and invest for the long term.
Improvements to, and reform of, the Barnett formula - the decades-old system used to determine how much money Wales gets from the UK Government.
Delivering the £14bn commitment by UK Government for investment in rail in Wales, to address years of underfunding compared with other parts of the UK.
Further UK-wide action on the cost of living, to support households across Wales.
Increased capital spending for Wales in the UK Government''s upcoming Autumn Budget to drive economic growth and invest in our infrastructure including hospitals and affordable housing.
Funding to address the legacy of our industrial past, including through the restoration of coal tips and the remediation of contaminated land.
Cabinet Minister for Finance Elin Jones said:
"I''m pleased to be able to meet with my counterparts from across the UK in what will be an important chance to work constructively together on the challenges facing all our nations.
"I''ll also be clear about what Wales needs. The way our funding is calculated hasn''t kept up with the real needs of people here. It''s outdated, and it''s not transparent enough. That must change.
"We''re up against a genuinely challenging financial backdrop – so what we''re asking for isn''t about special treatment for Wales but for a system that''s fair, that''s clear, and one that reflects the needs of our communities.
"That''s why today I can confirm the Welsh Government has formally proposed a joint review of the Wales Fiscal Framework, which I''ll be discussing in a one-to-one meeting with the Chief Secretary to the Treasury.
"This Welsh Government set out our expectations on day one that Wales both needs and deserves a fairer settlement on funding and powers.
"Throughout the day, I''ll be pressing the case for greater investment in Welsh rail, and for capital spending and cost of living support to be prioritised in the Autumn Budget.
“Wales and all its communities deserve fairness and equality."', 'https://media.service.gov.wales/news/welsh-finance-minister-to-press-uk-government-for-fairer-funding-at-cardiff-summit', '2026-09-16', '', '', '', '', '', 'Welsh Government', 'Finance; Cabinet Minister for Finance - Elin Jones', '', '', NULL, 63.0, 'Medium', 'digest', 'housing_supply', 'Planning & place', 'First Minister / Cabinet', 'Decision or commitment', 'I can confirm; affordable housing', 0, '2026-09-18T11:37:50.617984', 'newsroom:welsh-finance-minister-to-press-uk-government-for-fairer-funding-at-cardiff-summit', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a79bff7f9e47a4afe1a7', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes. And I have a number of other things, as I''m sure lots of others do as well, but I did want to touch on agricultural pollution. We talked a lot at the beginning of the meeting about the drought and hot weather, et cetera, so I wanted to welcome the announcement that''s come this morning that you will now relook and be more flexible on when slurry can be sprayed, essentially. I think I''ve heard a lot of people welcoming that already. With this point, there''s a careful balance to make between agricultural needs and also the environment, and I was happy to see that you''re looking at that in this announcement. And, potentially, it''s a kind of win-win example, maybe. So, I just wanted to hear more about what you were thinking through, I suppose, on that particular issue.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Anna Nicholl', '', '12178', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6865&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.238337', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772059', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a83df74ada03ca20247d', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'We''re coming to the end. We''ve got five minutes left and there are a number of areas we haven''t yet touched on. Is there anybody who wants to ask anything further on animal health and welfare before I move on? Because I know a couple of Members want to ask a few questions about agricultural pollution. I don''t know if there''s any closing questions in the last five minutes to the Minister. Is there anything on animal health and welfare? Gareth, do you want to ask—? No. You''re just nodding your head in agreement. Lovely. I know, Anna, you wanted to ask something on agricultural pollution.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6834&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.233006', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772054', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a921a838cbad53979a70', 'committee_transcript', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', 'Going on from what Clare''s just mentioned, from our experience, I think 28 days would be enough. I think that we were the only local authority within those 60 days to send a reminder out. So, we had three communications: the initial notification of registration; then about 25 days later we sent a reminder, a prompt—''You still have until the end of August to opt out of the automatic registration, but obviously the chance to register fully''; and then the final notification. With regard to the phone calls and the opt-outs, the early opt-outs with regard to concern about safety and safeguarding were all in the first tranche of phone calls. Anyone who wanted to explore or needed to consider anonymous registration all rang us within the first two weeks of receiving that communication. Any parents who felt strongly that their child should not be on the register at that age rang and wanted to opt them out at that point.

 During the reminder stage, or the prompt stage, as I call it, we did have opt-outs. We did have a handful, a very small number; we only had 28-odd for the whole of the mailout. But we had a few, and I took some of those phone calls myself—I happened to be in the office—and when I questioned, ''Why did you leave it until this point when you had the time?'', it was, ''I just put it on the mantelpiece'' or ''I put it in the recycling''. So, they weren''t concerned about their safety, they just wanted to opt out. They''d read it fully by then, considered it and obviously wanted to opt out at that stage. When we sent the final notification, again, we had, I think, just one person querying something, but nothing with regard to safeguarding. All those phone calls with concerns about their name appearing on a public register, or because of their safety or circumstance, all happened within the first tranche, and our team were able to advise them accordingly.

 So, based on that experience, I think 28 days would give sufficient time. I do think—and Clare made the point, and it was something that we experienced—that we need to have clear messaging on the envelope. It''s amazing how many people receive an envelope and don''t do anything with it. Certainly, that would also aid with the accuracy, where, if somebody has been matched and identified against the wrong property, what tends to happen is the householder just thinks, ''Oh, they might be the past occupier'' or that it''s a bureaucracy or admin error, and they just chuck it in the recycling. We need them to phone us. ''If this person does not live at your property, we need you to contact us immediately.'' And, again, with regard to safeguarding, there needs to be a clear message that if you do not wish to be automatically registered, you need to take action by a certain date, or immediately. So, I think there are mitigations around that, with clear communications and flagging that. 

 And I think—. We had a by-election. We had several by-elections, actually, during that 60-day period—never a quiet time—and, obviously, that 60-day period is quite difficult. You''re telling people they''re going to be on a register at a certain point, but, actually, there''s an election in the meantime. It''s about the messaging to the public. ''Oh, does that mean I can vote for this one?'' ''No, it doesn''t, you need to do something else.'' And 60 days was quite a long period for that, so I think 28 days probably sits better with an election timetable, because we don''t just have elections every four years, or even once a year; they happen throughout the year, so it''s something that, for the electorate, needs to be a bit more immediate.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Sandra Matthews', '', '', '', '', 'Local Government, Housing and Planning Committee', '3. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 2', '16256', 'http://www.senedd.tv/en/16256?startPos=4696&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:49.307709', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769957', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a9867f701767491f7cc4', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I''ve already raised, in the inter-ministerial mechanisms that we have, concerns around ensuring that farmers in Wales have a level playing field when it comes to some of those international agreements and arrangements that are in place. There is a risk that we find ourselves undermining a lot of the good work that''s happening in Wales around antimicrobial resistance, for example, public health as well, as well as the economic piece in terms of maybe a two-tier market here if we allow some of this to come in. Richard, are you keen to come in?', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5269&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.004396', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771864', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a9a87c74dccdefa727f4', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'I''ll bring forward the regulations required to implement the changes to the differential multipliers in the coming weeks. The regulations will specify the properties that will be subject to the lower multiplier, and amend the value used to calculate the higher multiplier relative to the standard multiplier for any given year. Subject to the approval of this Senedd, the changes will take place on 1 April 2027.

 The values of the multipliers for next year will be determined as part of our budget preparations for 2027-28, following the UK Government''s autumn budget. I''m proposing to make these changes at the earliest opportunity in this Senedd, to prioritise the improvements that are deliverable and affordable in the short term. The Welsh Government will continue to consider further reforms to the non-domestic rates system that reflect our broader ambitions for Wales. I know that Members across the Chamber are interested in this matter, and ideas for further measures on non-domestic rates will receive a listening ear from me. Diolch.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Elin Jones', '', '162', '', '', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', '16260', 'http://www.senedd.tv/en/16260?startPos=9588&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:26.023354', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769220', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('a9b42c4b2619bc4ccb7c', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'I think I responded to that question earlier, in response to Jane Dodds. Early next year is when we’ll be taking the strategy out for consultation.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=1328&l=en', NULL, 132.2, 'Critical', 'immediate', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', 'Consultation open', 'Equality, Human Rights and Social Justice Committee; consultation', 0, '2026-09-25T06:30:35.704545', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771204', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('aa0b2fc9655316b41ed4', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'I was wondering if you could provide the intended timeline for the introduction of legislation, if possible.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Kiera Marshall', '', '12166', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=276&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.078259', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770359', NULL, NULL, NULL, NULL);
