INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c71a701d11242cbcc4d7', 'plenary_transcript', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', 'I was speaking earlier with Gwyn, regretting the loss of Marks and Spencer in Swansea. Will there be more retailers of that kind that are likely to take decisions to close their stores in the middle of our cities?', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Huw Thomas', '', '12156', '', '', 'Plenary', '4. Statement by the Cabinet Minister for Finance: Rebalancing the non-domestic rates system', '16260', 'http://www.senedd.tv/en/16260?startPos=10158&l=en', NULL, 60.5, 'Medium', 'digest', 'taxation_of_property', 'Tax & finance', 'First Minister / Cabinet', '', 'non-domestic rates', 0, '2026-09-19T12:39:26.108614', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769223', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c738e2730f1c61a09232', 'legislation', 'Acts of Senedd Cymru', 'Building Safety (Wales) Act 2026', 'Building Safety (Wales) Act 2026', 'https://www.legislation.gov.uk/asc/2026/5/2026-04-28/data.xml', '2026-06-25', '', '', '', '', '', 'legislation.gov.uk', '', '', '', NULL, 84.5, 'Medium', 'digest', 'building_safety_and_leasehold; named_welsh_legislation', 'Context; Property & energy', '', '', 'Building Safety (Wales) Act; building safety', 0, '2026-08-04T14:04:14.611174', 'https://www.legislation.gov.uk/asc/data.feed', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c7434670951961497e74', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Just on that point, it''s 17 now. I know there are new Members around this table, so can you give us a sense of where it used to be and if there are any plans to change that?', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=702&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.160758', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770373', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c78ea9e504e87e8ee0d5', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'We could have a philosophical debate here about how many months is months. All I can say is that all the actions that have been taken by this Government within the first 100 days—. You know, commissioning that work on establishing the surgery hubs, on making sure that we put that investment through this supplementary budget that we want to get passed today, so that we can, both in capital spend and in resource spend, make that investment to drive down those two-year waits—. The actions that Government is taking are aligned with bringing down those two-year waits as quickly as we can. We want to do it in months. I not so much stick to that—that is precisely what we set out to do before coming into Government, and what we are actively delivering now in Government.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16085', 'http://www.senedd.tv/en/16085?startPos=937&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:08.266257', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767474', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c79342f5bbbdfd1354d6', 'calendar', 'Senedd diary (senedd.tv)', 'Equality, Human Rights and Social Justice Committee — 30 September 2026, 09.45', 'Equality, Human Rights and Social Justice Committee meets on 30 September 2026 at 09.45 in Committee Room 2.', 'https://business.senedd.wales/ieListDocuments.aspx?CId=983&MId=16248', '2026-09-30', '', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '', '16248', 'https://www.senedd.tv/Meeting/Index/099196e1-4b39-4da7-bb07-81264c8b621e', '2026-09-30', 24.0, 'Noise', 'archive', 'committee_scrutiny', 'Housing system', '', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-24T06:33:40.081930', 'seneddtv:099196e1-4b39-4da7-bb07-81264c8b621e', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c7dc39530a3c4557b3ad', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Well, I would hope that the planning system takes some of that into consideration. Clearly, the planning system is there for a reason. It''s both to protect interests and, also, to allow the right kind of development to happen in the right kind of place. So, I''m not sure what kind of infrastructure developments you''re thinking about particularly, but there will be examples where a balance has to be struck, and I would hope that the planning system takes that into consideration. But that doesn''t, sort of, hold back our ambition because those are, I''d imagine, isolated examples. We are clear that we want to get to a position where we halt the decline of nature by 2030 and it''s been restored by 2050. Now, that''s ambitious. That means that we need to make sure that we have those robust targets in place, those statutory targets, but that actions reflect that as well. And we are developing the climate and nature action plan, which is a big piece of work for us as a Government. Because at the minute, if you think, we have a whole sort of disparate landscape of legislation and strategies and action plans, and we really need to try and bring a coherence to that by bringing much of that together in a way that is action based and outcome focused, and that''s one big piece of work that we''re undertaking at the minute.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3235&l=en', NULL, 63.2, 'Medium', 'digest', 'planning_system; committee_scrutiny', 'Housing system; Planning & place', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; planning system', 0, '2026-09-25T06:30:34.777604', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771872', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c7f1e3c71be545d34921', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. I have one other question. When will you be able to return to the committee or when will we be able to see when exactly next year you will be putting forward the strategy and targets?', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Jane Dodds', '', '4983', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=744&l=en', NULL, 86.2, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Opposition housing leads', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.634015', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771191', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c80ef63e2ccdf8e149da', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes. It has been a live discussion and, obviously, given the pressures on the legislature in any event and on our counsel and legal services, if it''s possible to do it without legislating, provided we take the Senedd with us and have the necessary discussions, and so on, then it''s a way of dealing with matters within our current competence and ability to deliver.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5133&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.020926', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770530', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c82126a91afe2dbea1a0', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'I think the critical thing for EROs here will be considering very carefully which local data sets are going to be most useful to identify the particular challenges that you''ve already highlighted. So, is this an area with lots of students? Is this an area with a larger proportion of HMOs? Or, do we know that there is a higher turnover of population within a particular area? So, that might suggest, for example, that we need to look at the education data, we need to look at the university data, or we need to look at the housing department authority data, to give us the best type of data, and then to think about when best to use that. I think the minimum requirement is for the registration officers to carry out that one match activity across the whole authority area each year. So, there may be flexibility for them to do more than that. I think the key thing would be for that exercise to be underpinned by an analysis of which areas are likely to need more attention. And then, as we said, pinning that to particular data sources that are going to be more effective at identifying new voters.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'Tom Hawthorn', '', '', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1873&l=en', NULL, 109.2, 'High', 'digest', 'hmos_and_standards; committee_scrutiny', 'Housing system; Private rented sector', '', 'Opportunity to influence', 'HMOs; Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.971718', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769846', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c83565da51d2d40cffb5', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Budgets are about priorities, they''re about choices, and I''m afraid that this supplementary budget gets those things wrong. As the Cabinet Minister herself said, this budget honours the previous Welsh budget to the decimal point. And that''s the point. That''s why we disagree with it, because we disagreed with the previous Welsh Government''s budget as well, for the same fundamental reasons that we disagree with this one. You bleated on yet again today about the £300 million in-year pressures that you are facing as a Welsh Government. Well, that''s because of the budget that you signed up to as a party in the last Senedd earlier this year. So you can''t bleat about it when you fixed this previous budget from which you and the Welsh public and our Welsh public services are now facing the consequences.

 And I''m sorry, but it really does make me irate when I hear people complaining about decisions to invest in our defence industry to keep our country safe, which is what you implied earlier on about the decision being taken by the UK Government. I''m no friend of the UK Government, but I support investment in our defence industry because we need to make sure that we keep our country safe. And what we really need to do to pay for that is to cut welfare bills, get people back into work, and people off the benefits system.

 We all know that you''ve got over £400 million to spend, £327 million-worth of that is due to additional learning needs spend in England, yet not a single penny in your supplementary budget was being allocated to that spending line today. And I know there''s been some discussion between you and the Labour Party, but not a single penny in your original supplementary budget proposals was being allocated to additional learning needs. I think that is appalling. I really do think that''s appalling, especially when all of us in this Chamber, especially those who''ve been here for a long time, know full well the pressures that those schools are facing, know full well the pressures that parents are facing not getting the support for their children. It''s not good enough, and we need to shift the dial.

 Patients need the dial shifting too, and we need some honesty from the Minister about the funding for the NHS. You''ve talked about the additional resources that are available for health in the supplementary budget, but the reality of this budget before us today is that the NHS budget is still being cut in real terms. That is shameful. You''re cutting the NHS budget at a time when demand is rising and pressures are growing when compared to the previous financial year. It''s a statement of fact, First Minister. Would you like to get your calculator out? I''m happy to lend you mine if you want.

 People in Wales want to be treated in a hospital bed, not a corridor. They want an ambulance to come on time if they pick up the phone and it''s an emergency. They want to get an NHS dentist. They want to be able to get an appointment the same day that they phone their local GP. They can''t at the moment, and that''s why we need to invest in our NHS, not cut the NHS budget, which is what your supplementary budget is still allowing for, even though there''s extra cash available that you could be allocating.

 There''s also very little in this budget to help people with the rising cost of living. Where''s the action to help people keep their council tax bills down, which have been spiralling out of control year in, year out? Where''s the support for businesses in Wales, who are struggling with those sharp increases in their business rates? Where''s the support for pubs? Where''s the support for our high streets? Where''s the extra finance for our hospice and palliative sector, which is crying out for sustainable funding? And where''s the support for our farming industry as well? We need to make sure that supplementary budgets reflect the views and the wills of the people of Wales. But most of all, you''ve got that fundamental problem with the original budget, which you signed up to earlier in the year and you''re now carping on about. We''ll be voting against this supplementary budget today.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Darren Millar', '', '171', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=24391&l=en', NULL, 77.0, 'Medium', 'digest', 'taxation_of_property; fiscal_and_legislative_context', 'Context; Tax & finance', 'First Minister / Cabinet', '', 'business rates; council tax; supplementary budget', 0, '2026-08-04T14:03:10.634423', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767899', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c842a7c0d68ea1823de6', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'In my constituency, over the summer, we went to look at some wildfires; we went to look at the causes of them. And it was often—we witnessed it, because the fires were literally started by anti-social behaviour. I know it''s broadening the scope, again, of what the Government can do, but I think a lot of it is down to anti-social behaviour, people not understanding the origins of these fires, and I think that''s something that we need to deal with as well as a Government.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Gareth Beer', '', '8650', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2315&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.628438', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771930', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c86850a076de493ad078', 'legislation', 'Senedd Act', 'Homelessness and Social Housing Allocation (Wales) Act 2026', 'Homelessness and Social Housing Allocation (Wales) Act 2026
Current stage: Royal Assent (01 April 2026)
Stage history: Bill introduced 19 May 2025; Stage 1 04 Nov 2025; Stage 3 03 Feb 2026; Stage 3 11 Dec 2025; Stage 4 10 Feb 2026; Royal Assent 01 Apr 2026', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=45883', '2026-04-01', '', '', '', '', '', 'Senedd', '', '', '', NULL, 136.5, 'Critical', 'immediate', 'homelessness; social_housing; named_welsh_legislation', 'Context; Housing system', '', 'Bill progress', 'Homelessness and Social Housing Allocation; Homelessness and Social Housing Allocation (Wales) Act; Royal Assent; Stage 1; Stage 3; Stage 4; homelessness; social housing', 0, '2026-08-04T14:04:23.127470', 'https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=45883', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c8a1225da086695f3aea', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Beca, I''ll bring you in here now. Thank you.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Peredur Owen Griffiths', '', '8579', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=4254&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.839246', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770481', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c8ce4a807dca9d4d9822', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'John. You''re on mute, John. There we are. You''re away now. Don''t touch anything. I think they''ve unmuted you.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=3093&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.750663', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771906', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c8e4df1ae709bf8dccb8', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'The Member makes a very good point, and it''s an international problem. We have seen some big cities take action on Airbnb. We tend in Wales to look at the more popular seaside areas, because that''s where the problems are perceived to be more acute. But the Member is absolutely right that this is an issue that can arise anywhere. I (a) agree that it''s an issue, and (b) want us to look at all those solutions that can be put in place. Some have been introduced through co-operation between our parties in the last Government—changes that lead to changing behaviour through use of premiums on council tax and so on. But there are also planning changes that we should always be alive to considering, because I agree this is a significant issue. The main purpose of a house, a flat or an apartment is to be a home, and we should always bear that in mind.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Rhun ap Iorwerth', 'First Minister of Wales', '2717', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=2454&l=en', NULL, 99.0, 'High', 'digest', 'taxation_of_property; second_homes_and_short_term_lets', 'Planning & place; Tax & finance', 'First Minister / Cabinet', '', 'Airbnb; council tax', 0, '2026-09-19T12:39:25.164350', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#769010', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c8f3b4cf9703ca18a08a', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'So, we move on now to item No. 2, which is general scrutiny of the Cabinet Minister for Rural Resilience and Sustainability. Welcome, Minister. It''s good to see you on that side of the table for a change.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'James Evans', '', '8585', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=51&l=en', NULL, 46.0, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', 'Other committee chairs', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.271360', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771829', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c90b06b4d33309cdeb34', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you. Just to say in general that our programme for government, which was announced yesterday, reflects our determination, our objective as a Government to work with people, particularly those people who have lived experience, in terms of ensuring equality. And our focus, as we''ve already mentioned, is on delivering outputs that are real, tangible, that people can feel in their daily lives, and strengthening, then, the delivery of the programmes that we have to ensure that that happens. So, for example, in terms of gender equality, we do this across a number of our schemes with regard to equality, but gender equality is, of course, vital in this work. And ensuring that— . We know, for example, about the gender pay gap, don''t we? That''s something where it is clearly obvious that there is further work to be done when it comes to ensuring gender equality. And in my portfolio, we have the childcare offer, which I hope will make a difference and will ensure that more women can enter the world of work or increase their working hours, or can undertake training and education opportunities and so on that will enable them to overcome the barriers that do exist for mothers in particular.

 And then, of course, in terms of the economy and skills more generally, skills are something that other Ministers in the education department and in the economy department are looking at in terms of our objective to ensure that there is greater equality within the work and employability and apprenticeship programmes that we already have. And we heard about that from the First Minister yesterday, didn''t we, so I won''t rehearse those comments.

 In terms of gender budgeting specifically, perhaps I''ll pass you over to Amelia on that.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sioned Williams', '', '8670', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4357&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee; programme for government', 0, '2026-09-25T06:30:35.999508', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771300', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c9667ed684abdacd2285', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you very much. We are already taking action through the social housing grant and the transitional accommodation capital programme. This will tackle homelessness, reduce reliance on temporary accommodation and ensure that people across Wales have access to quality homes that are energy efficient. We''re also establishing Unnos to accelerate the delivery of social housing across Wales.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=5604&l=en', NULL, 104.5, 'High', 'digest', 'housing_supply; homelessness; social_housing', 'Housing system; Planning & place', 'Housing minister', '', 'Unnos; homelessness; social housing; temporary accommodation', 0, '2026-08-04T14:03:05.231002', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768213', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c9788d2435b317cfc9cb', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I fear I might be.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=7130&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.278880', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772091', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c9a68394626cf0a4a972', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'I think we have to be concerned if there are lapses or gaps in official controls in any country. Where there may be lapses or gaps from the point of view of official controls—it might be residues, it might be other sanitary and phytosanitary conditions—that''s naturally why we have the systems and processes in place at an official level that look at risk. So, it may be that we''re looking across the piece at disease threats, as another example, and the threats that products of animal origin might pose to our domestic farming systems, livestock health and welfare, and other animals, indeed. 

 If I just dwell on that for a moment, where we see those kinds of threats, we do risk assessments on a collective basis within Great Britain, and we take safeguard actions. Where we''ve seen diseases that we do not have in the UK that would be notifiable and exotic—peste des petits ruminants, for example, which has been in Europe, lumpy skin disease, and you will all recall, as a committee, foot and mouth disease in Europe in the last 18 months—we took safeguard measures, based upon risk assessment and evidence, to then prohibit imports from European nations. Where there are non-European nations that may be affected by diseases, we similarly do the risk assessment and we put safeguard measures to protect our animal health and welfare and all that stems from that, whether it''s the protection of public health, as the Minister rightly said, and I think you''re also alluding to, Andrew, in your question, from the point of view of things like antimicrobial resistance. We know that there are infectious diseases that can also affect public health. Bird flu is a clear example. Clearly, we''ve had several years of bird flu in the UK, but where there are other diseases that are zoonotic, we have to assess that risk from an animal health and welfare and public health point of view, working with our public health counterparts. 

 So, it''s all part of our risk management cycle, whether it''s looking at AMR official controls on the one hand, looking at disease threats that may pose direct risk to animal health and welfare, livestock, companion animals, equine, whatever, and all that flows from that. We''ve had a substantial discussion this morning around sustainability and resilience, and we recognise, again, as officials and at CVO level, we have to anticipate shocks to the system, and animal disease threats represent one of several shocks that can occur to the system. So on the one hand, we need to be prepared, we need to be assessing risk and contingency planning, and that''s a system-wide issue as well, right the way from the farm and individual premises level, all the way up to Government and back down again.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Richard Irvine', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=5390&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.021831', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771865', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c9d951cec561819b244a', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Bore da, bawb. I''m Rhodri Asby. I''m the interim director for environmental sustainability and climate change.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Rhodri Asby', '', '', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=91&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.286027', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771856', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c9e08490f3fefab55040', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'So, the UK currently spends—[ Interruption .] Oh, sorry. Am I all right to come back? I do apologise.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Joe Martin', '', '12146', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2016&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.776431', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771172', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('c9ed53ae3c6b9cb83341', 'plenary_transcript', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', 'Thank you for that question and for your interest in this particular area. During this Government''s first 100 days, we will be making a full announcement on the purpose of the new taskforce that we''re currently establishing and its membership. Of course, it''s the taskforce that will consider its specific remit, and I''m very eager for that to happen, rather than us, as a Government, setting out certain criteria. It''s the people in that taskforce, in consultation with others, that will set the remit for that work. But I assume, having been involved in this sort of work for years, that looking at business rates and how we can make sustaining a shop in a town centre more attractive than being located in an out-of-town centre would be one area that they would look at, along with planning and how we can accelerate the process in order to convert vacant buildings in our town centres. But there''s also this desire to look holistically at what public services can be brought into our town centres and how we can accelerate the planning process around that too. There''s a great job of work to be done, but it''s very exciting, and I look forward to working with the taskforce.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Sian Gwenllian', '', '4981', '', '', 'Plenary', '2. Questions to the Cabinet Minister for Local Government, Housing and Planning', '16086', 'http://www.senedd.tv/en/16086?startPos=4734&l=en', NULL, 115.5, 'High', 'digest', 'taxation_of_property', 'Tax & finance', 'Housing minister', 'Consultation open', 'business rates; consultation', 0, '2026-08-04T14:03:05.149829', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768157', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ca17e95c27b001e295e8', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Well, I think the first thing to say, Chair, is this: there have been unfortunate examples of late where the information required has not come through to us and, therefore, we can''t impart it to the Senedd, and, therefore, there are complaints that LCMs are late in being tabled—supplementary legislative consent memorandums, and so on, as well. What we need to do, it seems to me, is to get in early, speak clearly early with our colleagues in London so that we will then be able to give a proper, intelligible, intelligent steer, our view—it''s up to the Senedd to decide ''yes'' or ''no''—give a steer on the LCM. So, that seems to me to be a fairly obvious point, but it''s something that needs to be done. It''s time-consuming, but it needs to be done. Otherwise, there will be the possibility of an LCM being voted down when it was the Government view that it should not be, and you rightly identify that. But in order to counter that, we need to do the groundwork.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Elfyn Llwyd', '', '12193', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3715&l=en', NULL, 74.8, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'LCM; Legislation Committee', 0, '2026-09-22T11:55:09.730648', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770461', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ca3160562859a15d0ba9', 'press_release', 'Welsh Government — Announcement', 'Review on holiday let tax rules to support tourism and local communities', 'Review on holiday let tax rules to support tourism and local communities', 'https://www.gov.wales/review-on-holiday-let-tax-rules-to-support-tourism-and-local-communities?utm_source=rss-announcements&utm_medium=rss-feed&utm_campaign=announcements-Review+on+holiday+let+tax+rules+to+support+tourism+and+local+communities', '2026-07-30', '', '', '', '', '', 'Welsh Government', '', '', '', NULL, 31.5, 'Low', 'dashboard', 'second_homes_and_short_term_lets', 'Planning & place', '', '', 'holiday let', 0, '2026-09-02T11:36:04.898172', 'https://www.gov.wales/announcements/rss', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('caa7057df6b5de076f3c', 'plenary_transcript', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', 'Diolch, Lywydd. I''d like to thank all the Members who contributed to this evening''s debate. Let me begin with a concern that is widely shared across the Siambr: the way that this Bill was handled, which did curtail our ability to scrutinise it. The preceding legislation that led to the Scunthorpe operations being effectively put into Government control and then nationalised, of course, was an England-only Bill and it was passed, as I said earlier, in a day. This was a four-nation Bill. It relates not just to a potential move in relation to that one site, but it''s a piece of legislation that could be applied to steel operations anywhere in the United Kingdom. Given that, I think the approach should have reflected the devolution settlement.

 There was no prior engagement with the Welsh Government. The reason that has been given, I understand, is one of it being commercially confidential. Well, with something that is as strategically important to the future of the Welsh economy and the UK economy, then I don''t think that stands up to scrutiny, to be perfectly frank.

 We were put in a difficult position, as were the other devolved legislatures. The Northern Ireland Assembly hasn''t been able to arrive at a position because there''s been simply no time because of the compressed timetable. We, as we always will, will reflect on what we could have done differently, but, in essence, we were put in a very, very difficult position.

 What we tried to do was, given that suboptimal position, we tried to get the best result for Wales. Yes, the commitments that we sought in relation to Wales''s legitimate interests on behalf of our steel communities—we wanted that in statute, that those are our principles. I think they''re principles that will, I think, probably be widely shared right across this Siambr. Now, we were able, because we held out, to get those commitments, at least on the record, and we were successful at least in getting a commitment from the current UK Government. But if they were prepared to make that promise at the despatch box, why weren''t they prepared to put it in statute? Because the promise doesn''t change, the commitment doesn''t change, but, of course, a statutory commitment is always better because you can hold not just this Government to account, but, of course, it stands, then, in the legislation governing future administrations as well, and I simply don''t understand the resistance to putting it on a statutory basis.

 People have spoken rightly with feeling about Port Talbot, and I will not add further to what I said in opening, except this: we cannot restore what that community lost, but we can make certain that the option to nationalise is firmly available to future Governments if necessary, and that''s what consent today achieves, and it''s why, in all conscience, we could not do anything other than recommend to the Senedd that we support it. Of course, any policy in relation to nationalisation or wider steel strategy has to be fair, and we have to have fair competition, and I think we were right and other Members are right to raise that. Public ownership exists to rescue an industry, not to distort a market, and if these powers are used in Scunthorpe or anywhere else, we will measure the consequences against the interests of our Welsh steel industry, our Welsh steel companies and communities that depend on that sector, and we''ll not stay silent if Wales is made to pay the price of an intervention elsewhere.

 But our message today is simple: we consent to this Bill, or we urge the Senedd to do so, because Wales must never again be told that the tools to save our steel do not exist. We consent to this legislation with our eyes open and with our conditions on the record: equal treatment, fair competition and a full Welsh voice whenever these powers touch the interests of our people. Thank you.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Adam Price', 'Cabinet Minister for Enterprise, Connectivity and Energy', '5030', '', '', 'Plenary', '8. Legislative Consent Motion: Steel Industry (Nationalisation) Bill', '16085', 'http://www.senedd.tv/en/16085?startPos=21747&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'Legislative Consent Motion; devolution settlement', 0, '2026-08-04T14:03:10.401306', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767941', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cb2275f56cfb84c67179', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'It is indeed. We don''t need to be building houses that are the houses that need retrofitting in future, because there''s another cost. So, we must do as much as we can through the planning system and through the regulatory regime, to make sure that we''re building the right kinds of houses that are futureproofed. And coming back to our earlier discussion, we''ve spoken at length about keeping homes warm and insulating them for heating. But, of course, we are now realising that there''s a cooling element as well that needs to be considered in that. So, all of that is in the mix, really.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=4608&l=en', NULL, 103.5, 'High', 'digest', 'energy_efficiency; planning_system; committee_scrutiny', 'Housing system; Planning & place; Property & energy', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; planning system; retrofitting', 0, '2026-09-25T06:30:34.899111', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771944', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cb49c3ab2e566773dda2', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'And if I may—sorry—you are confident that you will put structures and measures in place to address that. And what''s the phrase? It takes two to tango.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Huw Thomas', '', '12156', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=3553&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:09.699789', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770450', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cb5c07c2e0c79c946bc7', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Welcome back. We now move to item 9, debate on the first supplementary budget 2026-27. I call on the Cabinet Minister for Finance to move the motion—Elin Jones.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=22625&l=en', NULL, 38.5, 'Low', 'dashboard', 'fiscal_and_legislative_context', 'Context', 'First Minister / Cabinet', '', 'supplementary budget', 0, '2026-08-04T14:03:10.439437', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767937', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cb9075d295d92e89a141', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'The firebreaks, yes. Well, yes, exactly—', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=905&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.396911', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771739', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cbccc9dbf6bd1cfb637a', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, jumping back quickly to bluetongue, and it''s a question I posed to you in the technical briefing. Obviously, we know with the vaccination—. I think you said before that prevention is the best way, isn''t it, when we''re talking about bluetongue. So, with the vaccination uptake, obviously the unions are pushing for the uptake, Welsh Government''s pushing for it as well, so it''s not for a lack of trying, but we''re still not seeing those numbers that we need to see really, especially from what we''ve seen in south-west England. I wouldn''t feel comfortable seeing, next summer, what could possibly happen with the vaccination levels that we''re at.

 What is causing that barrier, do you feel, for farmers to not take up that vaccination? And how are you as a Government going about trying to tackle those barriers as well? Because, of course, we need to see more of those vaccinations if we want to ensure that we don''t see what happened in south-west England happening here in Wales.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Niamh Salkeld', '', '12143', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=6254&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:35.140389', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772112', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cbe7a25643981c9151dd', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, I just wanted to come in on a different topic. With water, we''ve been fortunate in west Wales not to have had some of the fires to the extent they''ve been had elsewhere, but we''ve had a lot of difficulties with people experiencing water shortages or no water at all, and a lot of that has been down in south Ceredigion. Before the drought came in, this was happening. First of all, the system isn''t designed to cope with the level of water demand, so when the heat went up, people were using more water and the system couldn''t cope with it. They were trying to truck water around, and that''s to do with the geography and the design of the pipes. So there''s something that we need to tackle there that''s unlike other parts of Wales and the UK. And then also, with the heat, the way that the pipes are designed there, they can''t cope with the changes in the ground, basically, when it gets very dry and then very wet again, so we''ve had lots of burst pipes. There''s an awful lot of money going into fixing those burst pipes, and it doesn''t last for long. I''ve had constituents come that have had the pipes burst three times, they''ve been without water. It''s not a resilient system, so there''s something about how do you work with the water companies, perhaps looking at this now with new regulation. We really need to invest in a more resilient water infrastructure.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Anna Nicholl', '', '12178', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=605&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.357725', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771779', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cbea0b5fceae4959c8f7', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Thank you very much. Just following up from that, whilst it does seem a long time ago to many, the closure of Chwarae Teg—. I was someone who benefited from support from Chwarae Teg when I was setting up a social enterprise. I know that, at some point, we''ll be coming to the impact of funding for the third sector. Since Chwarae Teg has disappeared, we''ve got fewer women''s equality organisations in Wales, and less—. The impact—there was so much that Chwarae Teg did to address income for women in Wales. I think it was over £1 million that they brought to women''s incomes in Wales. So, it would be interesting to learn what could be done across portfolio to support women in the economy. Thank you.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Sarah Rees', '', '5196', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4525&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:36.016682', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771315', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cc01dc816e8f42ead919', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Go on.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Huw Irranca-Davies', 'Llywydd', '5053', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=26311&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:10.845088', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#768001', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cc19433869e07d279ad6', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'Yes, I think there''s a public education piece, but there are also those who are intent on doing damage, which again brings a different kind of challenge in terms of policing that, particularly in rural areas, remote areas, where that might be difficult. But, yes, the police also have a role to play in this discussion, absolutely, because we need to try and bear down on all of those aspects that have left us in the position we found ourselves in over the summer.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=2340&l=en', NULL, 34.5, 'Low', 'dashboard', 'committee_scrutiny', 'Housing system', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', 0, '2026-09-25T06:30:34.632909', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#771932', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cc71fdeda2241bc96743', 'committee_transcript', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', 'Yes, I think that''s the challenge. The downside to being effective, doing it and getting on with the job, is the potential lack of scrutiny. It comes back again to some of the points made here. You certainly shouldn''t be rushing to do something that might not have earned majority support in the Senedd. So, there is a degree of care and nuance in these discussions, which I think we as a Government need to recognise, and that''s appropriate for us to recognise.', 'https://record.senedd.wales/Committee/16254', '2026-09-21', 'Dafydd Trystan Davies', '', '12140', '', '', 'Legislation Committee', '3. General Scrutiny session with the Counsel General and the Cabinet Minister for Government Effectiveness and the Constitution', '16254', 'http://www.senedd.tv/en/16254?startPos=5206&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Legislation Committee', 0, '2026-09-22T11:55:10.034259', 'https://record.senedd.wales/XMLExport/Download?meetingID=16254&xmlDownloadType=EnglishTranscript#770535', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cd463452918c10b9ec2e', 'plenary_transcript', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', 'The Member will be aware that the previous Government set a number of targets and failed to reach them because they weren''t realistic. We are absolutely realistic in how we are investing this money into improving outcomes so that people are seen quicker. We know that we''ve got issues around gynaecology. We know we''ve got issues around cataracts. We know about orthopaedics. So, these are the things that we need to look at and improve. That''s why we''re going to set up the elective care hub, so that we can see people quicker, so that people can get their treatment within the time frame that is required, so that they improve and can get on with their lives. So, we''re absolutely clear. We''ve been clear all along. I''m not quite sure where these questions come from. Everything we''ve said in the past, we are sticking by. We will be achieving this in a matter of months. However, let me remind you that you and your colleagues and others here voted against the budget yesterday, which had £145 million in order to tackle this. So, let''s not have any crocodile tears that you are concerned about waiting lists. Clearly, you''re not. If you were, you''d have supported the supplementary budget so that we could get this money onto the front line to see people as soon as possible.', 'https://record.senedd.wales/Plenary/16086', '2026-07-15', 'Mabon ap Gwynfor', '', '269', '', '', 'Plenary', '1. Questions to the Cabinet Minister for Health and Care', '16086', 'http://www.senedd.tv/en/16086?startPos=756&l=en', NULL, 16.5, 'Noise', 'archive', 'fiscal_and_legislative_context', 'Context', '', '', 'supplementary budget', 0, '2026-08-04T14:03:04.743264', 'https://record.senedd.wales/XMLExport/Download?meetingID=16086&xmlDownloadType=EnglishTranscript#768055', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cd4e8f2e0b4a09a829d4', 'plenary_transcript', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', 'Llywydd, I move the motion and open the debate on the Welsh Government''s first supplementary budget for 2026-27. This supplementary budget is our first opportunity to propose changes to the full budget this year and to start the important process of ensuring that expenditure aligns with our priorities as a new Government. We are focusing, therefore, on a targeted allocation of resources and additional capital. This will enable us to make swift progress on our most important priorities as a Government, while also demonstrating that money is being managed prudently and that there is stability for public services and partners.

 Alongside this, as is usual in supplementary budgets, the budget makes formal adaptations to the general level of funds available to Wales in light of the spring statement and the main objectives of the UK Government for this financial year. It also includes a restatement of this year''s final budget to reflect the new ministerial portfolios. Moving a first supplementary budget is an early mechanism in the financial year to set out formally changes to the annual budget. The second supplementary budget is the final opportunity to finally formalise the allocations towards the end of a financial year.

 This first supplementary budget therefore makes £433 million of additional allocations. This includes £294 million for Welsh Government priorities, and £139 million for budgetary responsibility transfers. The balance of £246 million in unallocated resources and £29,000 in general capital has been held in reserves in the first supplementary budget in order to manage in-year pressures and to respond to priorities. This unallocated funding is our protection against the financial position that we have inherited and against the significant financial pressures that are unfunded within the year, including a total of over £300 million of overspend that the health service is currently reporting. Managing these in-year pressures is a significant challenge, and that challenge is made more difficult because of the tight funding framework that we work within. The unallocated resources funding is there as reserves to be allocated later to help us manage the current pressures in the system, if necessary. We cannot allocate that funding in its entirety so early in the financial year. The previous Government made similar allocations to the NHS in supplementary budgets at the end of the financial year: £200 million in 2025-26, £424 million in 2023-24.

 The Welsh Government''s settlement is directly linked, as we know, to decisions made by the UK Government. It can change, even in-year, up and down. Only a few days after I appeared before the Finance Committee, the UK Government announced its defence investment plan. That is expected to lead to a direct negative consequence for our capital budget this year. If the cut of 1 per cent anticipated hits all departments of Government equally, that will mean the loss of between £25 million and £30 million immediately during this financial year alone, and there is more to come.

 This is a supplementary budget.', 'https://record.senedd.wales/Plenary/16085', '2026-07-14', 'Elin Jones', 'Cabinet Minister for Finance', '162', '', '', 'Plenary', '9. Debate: The First Supplementary Budget 2026-27', '16085', 'http://www.senedd.tv/en/16085?startPos=22645&l=en', NULL, 71.5, 'Medium', 'digest', 'fiscal_and_legislative_context; committee_scrutiny', 'Context; Housing system', 'First Minister / Cabinet', '', 'Finance Committee; final budget; supplementary budget', 0, '2026-08-04T14:03:10.441935', 'https://record.senedd.wales/XMLExport/Download?meetingID=16085&xmlDownloadType=EnglishTranscript#767932', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cd6780e0d8b05df6cf17', 'plenary_transcript', 'Plenary', '1. Questions to the First Minister', 'I think it''s shameful and shameless of Reform UK to abandon our—[ Interruption .] It''s my job. To abandon and just to sideline net zero. The world is on fire. As the First Minister has said, you just needed to look and see and talk to the communities that we represent over the summer just to see how bad it is.

 To get back to the very good point raised by Gwyn in relation to the community energy issues, I was lucky enough to visit Hwb y Gors in the Amman valley, where community-owned wind turbines have paid for the renovation of the community centre there. But it took 10 years to secure planning permission, and we need to make it much easier for our communities to be able to own community energy. So, Prif Weinidog, what will you and the Government do to make sure that we accelerate this, so that, actually, communities can own that community energy and ensure that they see the benefits and we stop the world being on fire? Diolch yn fawr iawn.', 'https://record.senedd.wales/Plenary/16260', '2026-09-15', 'Jane Dodds', '', '4983', '', '', 'Plenary', '1. Questions to the First Minister', '16260', 'http://www.senedd.tv/en/16260?startPos=300&l=en', NULL, 77.0, 'Medium', 'digest', 'planning_system', 'Planning & place', 'First Minister / Cabinet; Opposition housing leads', '', 'planning permission', 0, '2026-09-16T11:53:07.066494', 'https://record.senedd.wales/XMLExport/Download?meetingID=16260&xmlDownloadType=EnglishTranscript#768965', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cdb753d255a7f5f99284', 'committee_transcript', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', 'I''ve got a concern with 28 days in regard to students. As you know, students move around quite a lot, especially on some courses where they''ve got to go out and go away to do their work, especially civil engineering, where they go out on site and they might be relocated to other parts of the country. So, I believe that 28 days is too short a period. I thought if it was 60 days, it would at least give them that opportunity to be back in their address to get that letter and fill it back in. That was one of the concerns I had. Because we are looking to get more students to vote, and if they''re not being given the chance to fill in these forms in a timely manner, I believe that, sometimes, we will lose that chance of getting them to vote, whereas, as we know, a lot of students don''t vote.', 'https://record.senedd.wales/Committee/16256', '2026-09-17', 'David Hughes', '', '12159', '', '', 'Local Government, Housing and Planning Committee', '2. The Representation of the People (Electoral Registration without Applications) (Electoral Reform) (Wales) Regulations 2026: Evidence session 1', '16256', 'http://www.senedd.tv/en/16256?startPos=1432&l=en', NULL, 103.5, 'High', 'digest', 'committee_scrutiny', 'Housing system', 'LGHP Committee members', 'Opportunity to influence', 'Local Government, Housing and Planning Committee; evidence session', 0, '2026-09-18T11:33:48.908997', 'https://record.senedd.wales/XMLExport/Download?meetingID=16256&xmlDownloadType=EnglishTranscript#769885', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('ce85631c591e19698948', 'committee_transcript', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', 'So, as you rightly say, the review happened and the previous Government set up a task and finish group to look at implementing the recommendations of the review on the ground. I have, since coming into office, tasked that group with prioritising the farming-by-calendar considerations and looking at the workbook requirements as well. One was clearly a commitment in terms of our manifesto, but it''s a message that''s coming back clearly from the sector as well. The latter, then, has come partly through the red tape review being led by John Davies as well. It''s been an early indication of one frustration when it comes to bureaucracy and duplication. So, they are looking at both of those. I will expect to hear back from them when the time is right. And I think I''m actually attending a meeting—who do I look at for this one—of theirs in due course, so that I can have an update. And as soon as there is something to say, I''m more than happy to convey that to committee, either directly from officials, myself or whoever you feel is appropriate.', 'https://record.senedd.wales/Committee/16233', '2026-09-23', 'Llyr Gruffydd', '', '425', '', '', 'Climate Change, Environment, Sustainability and Rural Affairs Committee', '2. General scrutiny of the Cabinet Minister for Rural Resilience and Sustainability', '16233', 'http://www.senedd.tv/en/16233?startPos=7021&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', '', 'Opportunity to influence', 'Climate Change, Environment, Sustainability and Rural Affairs Committee; task and finish group', 0, '2026-09-25T06:30:35.258734', 'https://record.senedd.wales/XMLExport/Download?meetingID=16233&xmlDownloadType=EnglishTranscript#772074', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cea02a049add19796db1', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Okay, we''ll move on to the next topic on the agenda. So, we''ll start with equality and social justice. Joe Martin.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Zaynub Akbar', '', '12141', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=4177&l=en', NULL, 69.0, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet; Other committee chairs', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.972733', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771229', NULL, NULL, NULL, NULL);
INSERT INTO items (uid, source_kind, source_name, title, body, url, item_date, speaker, speaker_role, speaker_id, party, constituency, forum, agenda_item, meeting_id, video_url, deadline, score, band, channel, themes, tiers, entities, signals, matched_terms, force_alert, collected_at, raw_ref, notified_at, reviewed_by, review_note, review_status) VALUES ('cea61000c40e260b08c4', 'committee_transcript', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', 'Absolutely, yes. So, we''ve got a steering group in place, independently chaired by Fran Targett, who is previously of—you probably know Fran well—Citizens Advice, which is looking for that collective shared ownership of this work and driving it forward. The first phase, putting in place the foundations, did a lot of work in the last couple of years on that, but we think it was very clear, specifically to that group, that the push now is for pace, to move from discussion to delivery and seeing that turning into quite a practical route-map. They''re currently working on their next phase route-map, hoping to look at that in October and share that with the First Minister to see what the next set of very practical steps are that show a move now to practical outcomes, and seeing a change in people''s experiences of benefits. So, that''s the next focus for the group: to translate the foundational work into practical action.', 'https://record.senedd.wales/Committee/16247', '2026-09-23', 'Claire Germain', '', '', '', '', 'Equality, Human Rights and Social Justice Committee', '2. General scrutiny session: Deputy First Minister and Cabinet Minister for Equality and Social Justice', '16247', 'http://www.senedd.tv/en/16247?startPos=2523&l=en', NULL, 57.5, 'Medium', 'digest', 'committee_scrutiny', 'Housing system', 'First Minister / Cabinet', '', 'Equality, Human Rights and Social Justice Committee', 0, '2026-09-25T06:30:35.839492', 'https://record.senedd.wales/XMLExport/Download?meetingID=16247&xmlDownloadType=EnglishTranscript#771169', NULL, NULL, NULL, NULL);
